package com.sailpainter;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/**
 * A picture for the sail: ARGB pixels row by row from the top left. Immutable once made, so the
 * studio can hand a fresh one to the client thread while the user carries on drawing.
 */
final class Design
{
	static final int MAX_SIZE = 512;

	private final int width;
	private final int height;
	private final int[] pixels;
	private final boolean blank;

	private Design(int width, int height, int[] pixels)
	{
		this.width = width;
		this.height = height;
		this.pixels = pixels;
		this.blank = isBlank(pixels);
	}

	/** A design holding a copy of the given pixels. */
	static Design of(int width, int height, int[] pixels)
	{
		if (width < 1 || height < 1 || width > MAX_SIZE || height > MAX_SIZE)
		{
			throw new IllegalArgumentException("Design size " + width + "x" + height);
		}
		if (pixels.length < width * height) throw new IllegalArgumentException("Too few pixels");
		int[] copy = new int[width * height];
		System.arraycopy(pixels, 0, copy, 0, copy.length);
		return new Design(width, height, copy);
	}

	static Design blank(int width, int height)
	{
		return of(width, height, new int[width * height]);
	}

	/** The image at its own size, or shrunk to fit a square of the given size if it is bigger. */
	static Design fromImage(BufferedImage image, int maxSize)
	{
		maxSize = Math.min(maxSize, MAX_SIZE);
		int width = image.getWidth();
		int height = image.getHeight();
		if (width > maxSize || height > maxSize)
		{
			double scale = Math.min((double) maxSize / width, (double) maxSize / height);
			width = Math.max(1, (int) Math.round(width * scale));
			height = Math.max(1, (int) Math.round(height * scale));
		}
		return fromImage(image, width, height);
	}

	/** The image stretched to exactly the given size, smoothly, since it is usually a photo. */
	static Design fromImage(BufferedImage image, int width, int height)
	{
		// Copied straight across when no scaling is needed, so saving and loading never shifts a colour.
		if (image.getWidth() == width && image.getHeight() == height)
		{
			return new Design(width, height, image.getRGB(0, 0, width, height, null, 0, width));
		}
		BufferedImage scaled = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = scaled.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
			g.drawImage(image, 0, 0, width, height, null);
		}
		finally
		{
			g.dispose();
		}
		return new Design(width, height, scaled.getRGB(0, 0, width, height, null, 0, width));
	}

	int width()
	{
		return width;
	}

	int height()
	{
		return height;
	}

	/** The pixels themselves, for reading only. */
	int[] pixels()
	{
		return pixels;
	}

	int pixel(int x, int y)
	{
		return pixels[y * width + x];
	}

	/** Nothing drawn at all, so there is nothing to put on the sail. */
	boolean isBlank()
	{
		return blank;
	}

	int[] copyPixels()
	{
		return pixels.clone();
	}

	/** Every pixel scaled to a new size without blending, so pixel art stays crisp. */
	Design resized(int newWidth, int newHeight)
	{
		int[] out = new int[newWidth * newHeight];
		for (int y = 0; y < newHeight; y++)
		{
			int sourceY = y * height / newHeight;
			for (int x = 0; x < newWidth; x++)
			{
				out[y * newWidth + x] = pixels[sourceY * width + x * width / newWidth];
			}
		}
		return of(newWidth, newHeight, out);
	}

	BufferedImage toImage()
	{
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		image.setRGB(0, 0, width, height, pixels, 0, width);
		return image;
	}

	private static boolean isBlank(int[] pixels)
	{
		for (int pixel : pixels)
		{
			if ((pixel >>> 24) != 0) return false;
		}
		return true;
	}
}

package com.sailpainter;

import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.Base64;
import java.util.Iterator;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.stream.ImageInputStream;

/** Turns designs into PNGs and back, for the disk and for sending to the party. */
final class DesignCodec
{
	/** Pictures opened from disk may be large photos, but nothing bigger than this. */
	static final int MAX_FILE_SIZE = 8192;
	/** A design sent to the party is shrunk until its PNG is no bigger than this. */
	static final int MAX_SHARED_BYTES = 24 * 1024;
	private static final int MIN_SHARED_SIZE = 16;

	private DesignCodec()
	{
	}

	static byte[] png(Design design) throws IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		if (!ImageIO.write(design.toImage(), "png", out)) throw new IOException("No PNG writer");
		return out.toByteArray();
	}

	/**
	 * Reads a picture, checking its size before any pixels are decoded, so a file or message that
	 * claims to be enormous is turned away rather than filling memory.
	 */
	static BufferedImage read(InputStream in, int maxSize) throws IOException
	{
		try (ImageInputStream stream = ImageIO.createImageInputStream(in))
		{
			if (stream == null) throw new IOException("Unreadable picture");
			Iterator<ImageReader> readers = ImageIO.getImageReaders(stream);
			if (!readers.hasNext()) throw new IOException("Not a picture");
			ImageReader reader = readers.next();
			try
			{
				reader.setInput(stream, true, true);
				int width = reader.getWidth(0);
				int height = reader.getHeight(0);
				if (width < 1 || height < 1 || width > maxSize || height > maxSize)
				{
					throw new IOException("Picture is " + width + "x" + height + ", more than " + maxSize + " allowed");
				}
				return reader.read(0);
			}
			finally
			{
				reader.dispose();
			}
		}
	}

	/** The design as text to send to the party, halved in size until it is small enough to send. */
	static String share(Design design) throws IOException
	{
		byte[] png = png(design);
		while (png.length > MAX_SHARED_BYTES && Math.min(design.width(), design.height()) / 2 >= MIN_SHARED_SIZE)
		{
			design = design.resized(design.width() / 2, design.height() / 2);
			png = png(design);
		}
		if (png.length > MAX_SHARED_BYTES) throw new IOException("Design too detailed to share");
		return Base64.getEncoder().encodeToString(png);
	}

	/** A design received from the party. Anything too large or not a picture is refused. */
	static Design unshare(String text) throws IOException
	{
		// Base64 takes four characters for every three bytes.
		if (text.length() > (MAX_SHARED_BYTES + 2) / 3 * 4) throw new IOException("Shared design too large");
		byte[] png;
		try
		{
			png = Base64.getDecoder().decode(text);
		}
		catch (IllegalArgumentException e)
		{
			throw new IOException("Shared design is not base64", e);
		}
		BufferedImage image = read(new ByteArrayInputStream(png), Design.MAX_SIZE);
		return Design.fromImage(image, Design.MAX_SIZE);
	}
}

package com.sailpainter;

import java.awt.Component;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.List;
import javax.swing.JOptionPane;
import net.runelite.client.util.Filepath;

/** Opening and saving pictures where the user chooses. Swing thread only. */
final class DesignFiles
{
	private static final String TITLE = "Sail Painter";

	private DesignFiles()
	{
	}

	/** Asks for a picture to open, or null if none was chosen or it could not be read. */
	static BufferedImage open(Component parent)
	{
		List<Filepath> chosen = new Filepath.Chooser()
			.setIsOpen()
			.setAcceptsFiles()
			.setDialogTitle("Open a picture for your sail")
			.addExtensionFilter("Pictures (PNG, JPG, GIF, BMP)", "png", "jpg", "jpeg", "gif", "bmp")
			.showDialog(parent);
		if (chosen.isEmpty()) return null;
		Filepath file = chosen.get(0);
		try (InputStream in = file.openInputStream())
		{
			return DesignCodec.read(in, DesignCodec.MAX_FILE_SIZE);
		}
		catch (IOException e)
		{
			error(parent, "Could not open " + file.getFileName() + ": " + e.getMessage());
			return null;
		}
	}

	static void save(Component parent, Design design)
	{
		List<Filepath> chosen = new Filepath.Chooser()
			.setIsSave()
			.setAcceptsFiles()
			.setDialogTitle("Save your sail picture")
			.addExtensionFilter("PNG picture", "png")
			.setDefaultExtension("png")
			.setFileName("sail.png")
			.showDialog(parent);
		if (chosen.isEmpty()) return;
		Filepath file = chosen.get(0);
		if (file.exists() && JOptionPane.showConfirmDialog(parent, file.getFileName() + " already exists. Replace it?", TITLE,
			JOptionPane.YES_NO_OPTION) != JOptionPane.YES_OPTION)
		{
			return;
		}
		try (OutputStream out = file.openOutputStream())
		{
			out.write(DesignCodec.png(design));
		}
		catch (IOException e)
		{
			error(parent, "Could not save " + file.getFileName() + ": " + e.getMessage());
		}
	}

	private static void error(Component parent, String message)
	{
		JOptionPane.showMessageDialog(parent, message, TITLE, JOptionPane.WARNING_MESSAGE);
	}
}

package com.sailpainter;

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import net.runelite.client.util.Filepath;

/** Keeps the current design as a PNG in the plugin's own data folder. Disk work, so never on the client thread. */
final class DesignStore
{
	private static final String FILE = "sail.png";
	private static final String TEMP = "sail.png.tmp";

	private final Filepath directory;

	DesignStore(Filepath directory)
	{
		this.directory = directory;
	}

	/** The saved design, or null if there is none yet. */
	Design load() throws IOException
	{
		Filepath file = directory.joinSegment(FILE);
		if (!file.isFile()) return null;
		try (InputStream in = file.openInputStream())
		{
			return Design.fromImage(DesignCodec.read(in, DesignCodec.MAX_FILE_SIZE), Design.MAX_SIZE);
		}
	}

	void save(Design design) throws IOException
	{
		if (!directory.isDirectory()) directory.createDirectories();
		// Written beside the real file and moved over it, so a crash mid-write cannot lose the old one.
		Filepath temp = directory.joinSegment(TEMP);
		try (OutputStream out = temp.openOutputStream())
		{
			out.write(DesignCodec.png(design));
		}
		Filepath file = directory.joinSegment(FILE);
		try
		{
			temp.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
		}
		catch (AtomicMoveNotSupportedException e)
		{
			temp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
		}
	}
}

package com.sailpainter;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.function.Consumer;

/** Ready-made designs to start from, drawn at whatever size the canvas is. */
enum Examples
{
	TEST_PATTERN("Test pattern", Examples::testPattern),
	JOLLY_ROGER("Jolly Roger", Examples::jollyRoger),
	STRIPES("Stripes", Examples::stripes);

	private static final int BASE = 128;

	private final String label;
	private final Consumer<Graphics2D> painter;

	Examples(String label, Consumer<Graphics2D> painter)
	{
		this.label = label;
		this.painter = painter;
	}

	@Override
	public String toString()
	{
		return label;
	}

	/** Drawn on a 128 square and stretched to the given size. */
	Design draw(int width, int height)
	{
		BufferedImage image = new BufferedImage(BASE, BASE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			painter.accept(g);
		}
		finally
		{
			g.dispose();
		}
		return Design.fromImage(image, width, height);
	}

	/** Shows which way up and which way round the picture lands: an arrow up, and letters that read wrongly when mirrored. */
	private static void testPattern(Graphics2D g)
	{
		g.setColor(new Color(0xd94141));
		g.fillRect(0, 0, 64, 64);
		g.setColor(new Color(0x41a85f));
		g.fillRect(64, 0, 64, 64);
		g.setColor(new Color(0x3d6fd9));
		g.fillRect(0, 64, 64, 64);
		g.setColor(new Color(0xe8c547));
		g.fillRect(64, 64, 64, 64);
		g.setColor(Color.WHITE);
		g.setStroke(new BasicStroke(6));
		g.drawRect(3, 3, 121, 121);

		g.fill(new Polygon(new int[]{64, 92, 74, 74, 54, 54, 36}, new int[]{14, 44, 44, 70, 70, 44, 44}, 7));
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 34));
		FontMetrics metrics = g.getFontMetrics();
		String text = "RL";
		g.setColor(Color.BLACK);
		g.drawString(text, 64 - metrics.stringWidth(text) / 2 + 2, 110);
		g.setColor(Color.WHITE);
		g.drawString(text, 64 - metrics.stringWidth(text) / 2, 108);
	}

	private static void jollyRoger(Graphics2D g)
	{
		g.setColor(new Color(0x16, 0x16, 0x18));
		g.fillRect(0, 0, BASE, BASE);
		Color bone = new Color(0xf2, 0xee, 0xe3);

		// Crossed bones behind the skull.
		g.setColor(bone);
		for (double angle : new double[]{Math.PI / 4, -Math.PI / 4})
		{
			AffineTransform saved = g.getTransform();
			g.rotate(angle, 64, 78);
			g.fill(new RoundRectangle2D.Double(18, 73, 92, 10, 10, 10));
			for (int end : new int[]{18, 110})
			{
				g.fill(new Ellipse2D.Double(end - 8, 67, 14, 12));
				g.fill(new Ellipse2D.Double(end - 8, 77, 14, 12));
			}
			g.setTransform(saved);
		}

		// The skull.
		g.fill(new Ellipse2D.Double(34, 18, 60, 54));
		g.fill(new RoundRectangle2D.Double(46, 58, 36, 24, 10, 10));
		g.setColor(new Color(0x16, 0x16, 0x18));
		g.fill(new Ellipse2D.Double(44, 38, 16, 16));
		g.fill(new Ellipse2D.Double(68, 38, 16, 16));
		g.fill(new Polygon(new int[]{64, 59, 69}, new int[]{56, 66, 66}, 3));
		g.setStroke(new BasicStroke(2));
		for (int x = 52; x <= 76; x += 6) g.drawLine(x, 72, x, 81);
	}

	private static void stripes(Graphics2D g)
	{
		Color[] colours = {new Color(0xc0392b), Color.WHITE};
		int stripe = BASE / 8;
		for (int i = 0; i < 8; i++)
		{
			g.setColor(colours[i % 2]);
			g.fillRect(0, i * stripe, BASE, stripe);
		}
	}
}

