package com.sailpainter;

/**
 * The studio's drawing operations on a grid of ARGB pixels, row by row from the top left. With
 * mirror on, everything is drawn again reflected left to right, for symmetrical designs.
 */
final class PixelOps
{
	private PixelOps()
	{
	}

	/** A round dab of the given diameter centred on a pixel; even sizes centre on its top left corner. */
	static void dab(int[] pixels, int width, int height, int x, int y, int size, int colour, boolean mirror)
	{
		dab(pixels, width, height, x, y, size, colour);
		if (mirror) dab(pixels, width, height, width - 1 - x + (size % 2 == 0 ? 1 : 0), y, size, colour);
	}

	/** Dabs all along a line, so fast strokes leave no gaps. */
	static void line(int[] pixels, int width, int height, int x0, int y0, int x1, int y1, int size, int colour, boolean mirror)
	{
		int dx = Math.abs(x1 - x0);
		int dy = -Math.abs(y1 - y0);
		int stepX = x0 < x1 ? 1 : -1;
		int stepY = y0 < y1 ? 1 : -1;
		int error = dx + dy;
		int x = x0;
		int y = y0;
		while (true)
		{
			dab(pixels, width, height, x, y, size, colour, mirror);
			if (x == x1 && y == y1) return;
			int twice = 2 * error;
			if (twice >= dy)
			{
				error += dy;
				x += stepX;
			}
			if (twice <= dx)
			{
				error += dx;
				y += stepY;
			}
		}
	}

	/** Fills the patch of exactly matching colour around a pixel, edge to edge. */
	static void fill(int[] pixels, int width, int height, int x, int y, int colour, boolean mirror)
	{
		fill(pixels, width, height, x, y, colour);
		if (mirror) fill(pixels, width, height, width - 1 - x, y, colour);
	}

	static void rectangle(int[] pixels, int width, int height, int x0, int y0, int x1, int y1, int size, int colour, boolean filled, boolean mirror)
	{
		shape(pixels, width, height, x0, y0, x1, y1, size, colour, filled, mirror, false);
	}

	static void ellipse(int[] pixels, int width, int height, int x0, int y0, int x1, int y1, int size, int colour, boolean filled, boolean mirror)
	{
		shape(pixels, width, height, x0, y0, x1, y1, size, colour, filled, mirror, true);
	}

	/** Stretches the corner pixels apart so that a drag from one to the other covers both. */
	private static void shape(int[] pixels, int width, int height, int x0, int y0, int x1, int y1, int size, int colour,
		boolean filled, boolean mirror, boolean round)
	{
		shape(pixels, width, height, Math.min(x0, x1), Math.min(y0, y1), Math.max(x0, x1), Math.max(y0, y1), size, colour, filled, round);
		if (mirror)
		{
			shape(pixels, width, height, width - 1 - Math.max(x0, x1), Math.min(y0, y1), width - 1 - Math.min(x0, x1), Math.max(y0, y1), size, colour, filled, round);
		}
	}

	private static void shape(int[] pixels, int width, int height, int left, int top, int right, int bottom, int size, int colour,
		boolean filled, boolean round)
	{
		int boxWidth = right - left + 1;
		int boxHeight = bottom - top + 1;
		boolean[] inside = new boolean[boxWidth * boxHeight];
		float radiusX = boxWidth / 2f;
		float radiusY = boxHeight / 2f;
		for (int y = 0; y < boxHeight; y++)
		{
			for (int x = 0; x < boxWidth; x++)
			{
				if (!round)
				{
					inside[y * boxWidth + x] = true;
					continue;
				}
				float nx = (x + 0.5f - radiusX) / radiusX;
				float ny = (y + 0.5f - radiusY) / radiusY;
				inside[y * boxWidth + x] = nx * nx + ny * ny <= 1.0001f;
			}
		}
		for (int y = 0; y < boxHeight; y++)
		{
			for (int x = 0; x < boxWidth; x++)
			{
				if (!inside[y * boxWidth + x]) continue;
				boolean edge = x == 0 || y == 0 || x == boxWidth - 1 || y == boxHeight - 1
					|| !inside[y * boxWidth + x - 1] || !inside[y * boxWidth + x + 1]
					|| !inside[(y - 1) * boxWidth + x] || !inside[(y + 1) * boxWidth + x];
				if (filled) set(pixels, width, height, left + x, top + y, colour);
				if (edge) dab(pixels, width, height, left + x, top + y, size, colour);
			}
		}
	}

	private static void dab(int[] pixels, int width, int height, int x, int y, int size, int colour)
	{
		if (size <= 2)
		{
			for (int dy = 0; dy < size; dy++)
			{
				for (int dx = 0; dx < size; dx++) set(pixels, width, height, x - size / 2 + dx, y - size / 2 + dy, colour);
			}
			return;
		}
		// Pixel centres within the circle; the slack rounds off the corners less harshly at small sizes.
		float radius = size / 2f;
		float limit = radius * radius + 0.5f;
		int start = -(size / 2);
		float centre = start + radius;
		for (int dy = start; dy < start + size; dy++)
		{
			for (int dx = start; dx < start + size; dx++)
			{
				float ox = dx + 0.5f - centre;
				float oy = dy + 0.5f - centre;
				if (ox * ox + oy * oy <= limit) set(pixels, width, height, x + dx, y + dy, colour);
			}
		}
	}

	private static void fill(int[] pixels, int width, int height, int x, int y, int colour)
	{
		if (x < 0 || y < 0 || x >= width || y >= height) return;
		int target = pixels[y * width + x];
		if (target == colour) return;
		int[] stack = new int[width * height];
		int top = 0;
		stack[top++] = y * width + x;
		pixels[y * width + x] = colour;
		while (top > 0)
		{
			int index = stack[--top];
			int px = index % width;
			int py = index / width;
			if (px > 0 && pixels[index - 1] == target)
			{
				pixels[index - 1] = colour;
				stack[top++] = index - 1;
			}
			if (px < width - 1 && pixels[index + 1] == target)
			{
				pixels[index + 1] = colour;
				stack[top++] = index + 1;
			}
			if (py > 0 && pixels[index - width] == target)
			{
				pixels[index - width] = colour;
				stack[top++] = index - width;
			}
			if (py < height - 1 && pixels[index + width] == target)
			{
				pixels[index + width] = colour;
				stack[top++] = index + width;
			}
		}
	}

	private static void set(int[] pixels, int width, int height, int x, int y, int colour)
	{
		if (x >= 0 && y >= 0 && x < width && y < height) pixels[y * width + x] = colour;
	}
}

package com.sailpainter;

/** Places model vertices on screen the way the client does. */
interface Projector
{
	/**
	 * Fills in where each model-space vertex lands on the canvas, and one over its distance from the
	 * camera, or 0 for a vertex too close to the camera to place.
	 *
	 * @param orientation the model's turn, in the game's 2048ths of a circle
	 */
	void project(int count, float[] x, float[] y, float[] z, int localX, int localY, int localZ, int orientation,
		float[] screenX, float[] screenY, float[] inverseDepth);
}

package com.sailpainter;

import java.util.Arrays;

/**
 * One sail model copied out of the client for one frame and worked out ready to paint: which faces
 * are cloth, where each cloth corner falls on the picture, how brightly the game lights it, and
 * where it all lands on screen. It works on plain arrays so that it can be tested without a client.
 *
 * <p>Model space is the game's: x and z across the ground, y pointing down.
 */
final class SailMesh
{
	static final byte HIDDEN = 0;
	static final byte SOLID = 1;
	static final byte CLOTH = 2;

	/** A colour has to cover this share of the main cloth colour's area to count as cloth too. */
	private static final float CLOTH_SHARE = 0.25f;
	/** Faces at least this transparent are glass or haze, and do not hide what is behind them. */
	static final int SEE_THROUGH = 128;
	private static final int MAX_COLOURS = 64;
	private static final float MIN_SHADE = 0.25f;
	private static final float MAX_SHADE = 2f;
	/** How finely the cloth's outline is traced when fitting the picture inside it. */
	static final int FIT_GRID = 64;
	/** A fitted rectangle that moves less than this from last frame's is left where it was, so the picture holds still as the cloth billows. */
	private static final float FIT_SETTLE = 1.5f / FIT_GRID;

	int vertexCount;
	float[] x = new float[0];
	float[] y = new float[0];
	float[] z = new float[0];

	int faceCount;
	int[] a = new int[0];
	int[] b = new int[0];
	int[] c = new int[0];
	byte[] kind = new byte[0];
	int clothFaces;

	/** Where each vertex lies on the cloth laid flat, from 0 to 1 across and down. Set for cloth vertices only. */
	float[] u = new float[0];
	float[] v = new float[0];
	/** The part of the flattened cloth the picture is stretched over, as left, top, right, bottom. */
	float fitLeft;
	float fitTop;
	float fitRight = 1;
	float fitBottom = 1;
	/** How brightly the game lights each corner of each cloth face, three to a face, against the face's unlit colour. */
	float[] shade = new float[0];

	float[] screenX = new float[0];
	float[] screenY = new float[0];
	/** One over the distance from the camera, or 0 for a vertex too close to put on screen. */
	float[] inverseDepth = new float[0];

	private final int[] colours = new int[MAX_COLOURS];
	private final float[] colourArea = new float[MAX_COLOURS];
	private int[] faceColour = new int[0];
	private float[] faceArea = new float[0];
	private boolean[] inCloth = new boolean[0];
	private final boolean[] covered = new boolean[FIT_GRID * FIT_GRID];
	private final int[] heights = new int[FIT_GRID];
	private final int[] stack = new int[FIT_GRID + 1];

	/**
	 * Copies the model and works out its cloth. The colour arrays are the client's lit colours, where
	 * a third colour of -2 hides a face and -1 shades it flat in the first colour.
	 */
	void build(int vertexCount, float[] vx, float[] vy, float[] vz,
		int faceCount, int[] f1, int[] f2, int[] f3,
		int[] colours1, int[] colours2, int[] colours3,
		short[] unlitColours, short[] textures, byte[] transparencies, boolean wholeModel)
	{
		allocate(vertexCount, faceCount);
		this.vertexCount = vertexCount;
		this.faceCount = faceCount;
		System.arraycopy(vx, 0, x, 0, vertexCount);
		System.arraycopy(vy, 0, y, 0, vertexCount);
		System.arraycopy(vz, 0, z, 0, vertexCount);
		System.arraycopy(f1, 0, a, 0, faceCount);
		System.arraycopy(f2, 0, b, 0, faceCount);
		System.arraycopy(f3, 0, c, 0, faceCount);

		classify(colours1, colours3, unlitColours, textures, transparencies, wholeModel);
		if (clothFaces == 0) return;
		mapPicture();
		shade(colours1, colours2, colours3, unlitColours, textures);
	}

	/** Puts every vertex on screen at a position in its world view. */
	void project(Projector projector, int localX, int localY, int localZ, int orientation)
	{
		projector.project(vertexCount, x, y, z, localX, localY, localZ, orientation, screenX, screenY, inverseDepth);
	}

	/** On screen and facing the camera. The game culls the other side of every face, and so does this. */
	boolean visible(int face)
	{
		int i = a[face], j = b[face], k = c[face];
		if (inverseDepth[i] <= 0 || inverseDepth[j] <= 0 || inverseDepth[k] <= 0) return false;
		return screenArea(face) < 0;
	}

	/** Twice the signed area of a face on screen. Negative when it faces the camera. */
	float screenArea(int face)
	{
		int i = a[face], j = b[face], k = c[face];
		return (screenX[j] - screenX[i]) * (screenY[k] - screenY[i]) - (screenY[j] - screenY[i]) * (screenX[k] - screenX[i]);
	}

	/**
	 * Whether the picture would read back to front as things stand. A face shows the picture the right
	 * way round when its corners go round the same way on the picture as on screen; this asks which
	 * way most of the visible cloth goes, so the whole sail flips at once when the camera crosses it.
	 */
	boolean mirrored()
	{
		float forwards = 0;
		float backwards = 0;
		for (int f = 0; f < faceCount; f++)
		{
			if (kind[f] != CLOTH || !visible(f)) continue;
			int i = a[f], j = b[f], k = c[f];
			float pictureArea = (u[j] - u[i]) * (v[k] - v[i]) - (v[j] - v[i]) * (u[k] - u[i]);
			float area = -screenArea(f);
			// Visible faces have negative screen area, so matching picture area means the right way round.
			if (pictureArea < 0) forwards += area;
			else if (pictureArea > 0) backwards += area;
		}
		return backwards > forwards;
	}

	/**
	 * The screen area the visible cloth covers as {min x, min y, max x, max y} merged into the given
	 * bounds, or false if no cloth is visible.
	 */
	boolean addClothBounds(float[] bounds)
	{
		boolean any = false;
		for (int f = 0; f < faceCount; f++)
		{
			if (kind[f] != CLOTH || !visible(f)) continue;
			any = true;
			include(bounds, a[f]);
			include(bounds, b[f]);
			include(bounds, c[f]);
		}
		return any;
	}

	/** Puts every face that is not cloth into the depth buffer, so ropes and spars can cover the picture. */
	void occlude(SailRaster raster)
	{
		for (int f = 0; f < faceCount; f++)
		{
			if (kind[f] != SOLID || !visible(f)) continue;
			int i = a[f], j = b[f], k = c[f];
			raster.occlude(screenX[i], screenY[i], inverseDepth[i], screenX[j], screenY[j], inverseDepth[j], screenX[k], screenY[k], inverseDepth[k]);
		}
	}

	/** Paints the picture over the visible cloth. The depth buffer sorts out folds that overlap. */
	void paint(SailRaster raster, boolean flip)
	{
		float scale = shadeScale();
		for (int f = 0; f < faceCount; f++)
		{
			if (kind[f] != CLOTH || !visible(f)) continue;
			int i = a[f], j = b[f], k = c[f];
			raster.paint(
				screenX[i], screenY[i], inverseDepth[i], pictureX(i, flip), pictureY(i), lit(f * 3, scale),
				screenX[j], screenY[j], inverseDepth[j], pictureX(j, flip), pictureY(j), lit(f * 3 + 1, scale),
				screenX[k], screenY[k], inverseDepth[k], pictureX(k, flip), pictureY(k), lit(f * 3 + 2, scale));
		}
	}

	/** Spreads the picture over the whole of the cloth's flattened outline, corners and all. */
	void stretch()
	{
		fitLeft = 0;
		fitTop = 0;
		fitRight = 1;
		fitBottom = 1;
	}

	/**
	 * Puts the picture in the largest upright rectangle the cloth covers completely, laid flat. A
	 * square sail keeps the whole of its area; a triangular one gets the biggest box that fits inside
	 * it, so no part of the picture falls off the cloth.
	 *
	 * @param previous left, top, right and bottom from last frame for this sail, all zero the first
	 *                 time. Kept if the new rectangle is only a little different, and updated otherwise.
	 */
	void fitInside(float[] previous)
	{
		traceOutline();

		// The largest rectangle of covered cells: each row is the floor of a histogram of how many covered cells stand above it.
		int bestArea = 0, bestLeft = 0, bestTop = 0, bestRight = 0, bestBottom = 0;
		Arrays.fill(heights, 0);
		for (int row = 0; row < FIT_GRID; row++)
		{
			for (int column = 0; column < FIT_GRID; column++)
			{
				heights[column] = covered[row * FIT_GRID + column] ? heights[column] + 1 : 0;
			}
			int top = 0;
			for (int column = 0; column <= FIT_GRID; column++)
			{
				int height = column == FIT_GRID ? 0 : heights[column];
				while (top > 0 && heights[stack[top - 1]] >= height)
				{
					int tallest = heights[stack[--top]];
					int left = top == 0 ? 0 : stack[top - 1] + 1;
					int area = tallest * (column - left);
					if (area > bestArea)
					{
						bestArea = area;
						bestLeft = left;
						bestRight = column;
						bestTop = row + 1 - tallest;
						bestBottom = row + 1;
					}
				}
				stack[top++] = column;
			}
		}

		if (bestArea == 0)
		{
			stretch();
			return;
		}
		float left = (float) bestLeft / FIT_GRID;
		float top = (float) bestTop / FIT_GRID;
		float right = (float) bestRight / FIT_GRID;
		float bottom = (float) bestBottom / FIT_GRID;
		boolean settled = previous[2] > previous[0]
			&& Math.abs(left - previous[0]) <= FIT_SETTLE && Math.abs(top - previous[1]) <= FIT_SETTLE
			&& Math.abs(right - previous[2]) <= FIT_SETTLE && Math.abs(bottom - previous[3]) <= FIT_SETTLE;
		if (!settled)
		{
			previous[0] = left;
			previous[1] = top;
			previous[2] = right;
			previous[3] = bottom;
		}
		fitLeft = previous[0];
		fitTop = previous[1];
		fitRight = previous[2];
		fitBottom = previous[3];
	}

	/** Marks every cell of the flattened cloth's grid whose middle some cloth face covers. */
	private void traceOutline()
	{
		Arrays.fill(covered, false);
		for (int f = 0; f < faceCount; f++)
		{
			if (kind[f] != CLOTH) continue;
			float u0 = u[a[f]] * FIT_GRID, v0 = v[a[f]] * FIT_GRID;
			float u1 = u[b[f]] * FIT_GRID, v1 = v[b[f]] * FIT_GRID;
			float u2 = u[c[f]] * FIT_GRID, v2 = v[c[f]] * FIT_GRID;
			float area = (u1 - u0) * (v2 - v0) - (v1 - v0) * (u2 - u0);
			if (area == 0) continue;
			int minColumn = Math.max(0, (int) Math.floor(Math.min(u0, Math.min(u1, u2))));
			int maxColumn = Math.min(FIT_GRID - 1, (int) Math.ceil(Math.max(u0, Math.max(u1, u2))));
			int minRow = Math.max(0, (int) Math.floor(Math.min(v0, Math.min(v1, v2))));
			int maxRow = Math.min(FIT_GRID - 1, (int) Math.ceil(Math.max(v0, Math.max(v1, v2))));
			for (int row = minRow; row <= maxRow; row++)
			{
				float py = row + 0.5f;
				for (int column = minColumn; column <= maxColumn; column++)
				{
					float px = column + 0.5f;
					float w0 = ((u2 - u1) * (py - v1) - (v2 - v1) * (px - u1)) / area;
					float w1 = ((u0 - u2) * (py - v2) - (v0 - v2) * (px - u2)) / area;
					float w2 = ((u1 - u0) * (py - v0) - (v1 - v0) * (px - u0)) / area;
					if (w0 >= -0.001f && w1 >= -0.001f && w2 >= -0.001f) covered[row * FIT_GRID + column] = true;
				}
			}
		}
	}

	/** Across the picture, from 0 to 1, with anything outside that range off the picture. */
	private float pictureX(int vertex, boolean flip)
	{
		float across = (u[vertex] - fitLeft) / (fitRight - fitLeft);
		return flip ? 1 - across : across;
	}

	private float pictureY(int vertex)
	{
		return (v[vertex] - fitTop) / (fitBottom - fitTop);
	}

	/**
	 * What the shading is divided by so that the cloth in view averages 1. Taken over the side being
	 * looked at rather than the whole sail, so the picture keeps its own colours from either side
	 * instead of washing out on the sunny one and going murky on the other.
	 */
	float shadeScale()
	{
		double total = 0;
		double area = 0;
		for (int f = 0; f < faceCount; f++)
		{
			if (kind[f] != CLOTH || !visible(f)) continue;
			total += (shade[f * 3] + shade[f * 3 + 1] + shade[f * 3 + 2]) / 3 * faceArea[f];
			area += faceArea[f];
		}
		return area > 0 && total > 0 ? (float) (area / total) : 1;
	}

	private float lit(int corner, float scale)
	{
		return Math.max(MIN_SHADE, Math.min(MAX_SHADE, shade[corner] * scale));
	}

	private void include(float[] bounds, int vertex)
	{
		bounds[0] = Math.min(bounds[0], screenX[vertex]);
		bounds[1] = Math.min(bounds[1], screenY[vertex]);
		bounds[2] = Math.max(bounds[2], screenX[vertex]);
		bounds[3] = Math.max(bounds[3], screenY[vertex]);
	}

	/**
	 * Sorts faces into hidden, solid and cloth. The cloth is the colour (or texture) covering the most
	 * area, plus any other colour covering a good share of that, which leaves out ropes, trim and spars.
	 */
	private void classify(int[] colours1, int[] colours3, short[] unlitColours, short[] textures, byte[] transparencies, boolean wholeModel)
	{
		int colourCount = 0;
		for (int f = 0; f < faceCount; f++)
		{
			faceColour[f] = -1;
			boolean seeThrough = transparencies != null && (transparencies[f] & 0xff) >= SEE_THROUGH;
			if (colours3[f] == -2 || seeThrough)
			{
				kind[f] = HIDDEN;
				continue;
			}
			kind[f] = SOLID;
			faceArea[f] = modelArea(f);

			int key;
			if (textures != null && textures[f] != -1) key = 0x10000 | (textures[f] & 0xffff);
			else if (unlitColours != null) key = unlitColours[f] & 0xffff;
			// Lit colours keep the hue and saturation of the unlit one, and only the lightness varies.
			else key = 0x20000 | ((colours1[f] >> 7) & 0x1ff);

			int index = 0;
			while (index < colourCount && colours[index] != key) index++;
			if (index == colourCount)
			{
				if (colourCount == MAX_COLOURS) continue;
				colours[colourCount] = key;
				colourArea[colourCount] = 0;
				colourCount++;
			}
			faceColour[f] = index;
			colourArea[index] += faceArea[f];
		}

		float largest = 0;
		for (int i = 0; i < colourCount; i++) largest = Math.max(largest, colourArea[i]);

		clothFaces = 0;
		if (largest <= 0) return;
		for (int f = 0; f < faceCount; f++)
		{
			if (kind[f] == HIDDEN) continue;
			int colour = faceColour[f];
			boolean cloth = wholeModel || (colour >= 0 && colourArea[colour] >= largest * CLOTH_SHARE);
			if (cloth)
			{
				kind[f] = CLOTH;
				clothFaces++;
			}
		}
	}

	/**
	 * Lays the picture flat across the cloth: down is the model's own down, and across is the way the
	 * cloth stretches furthest over the ground, so a sail turned to the wind keeps its picture.
	 */
	private void mapPicture()
	{
		for (int i = 0; i < vertexCount; i++) inCloth[i] = false;
		for (int f = 0; f < faceCount; f++)
		{
			if (kind[f] != CLOTH) continue;
			inCloth[a[f]] = true;
			inCloth[b[f]] = true;
			inCloth[c[f]] = true;
		}

		double meanX = 0;
		double meanZ = 0;
		int count = 0;
		for (int i = 0; i < vertexCount; i++)
		{
			if (!inCloth[i]) continue;
			meanX += x[i];
			meanZ += z[i];
			count++;
		}
		meanX /= count;
		meanZ /= count;

		double xx = 0;
		double xz = 0;
		double zz = 0;
		for (int i = 0; i < vertexCount; i++)
		{
			if (!inCloth[i]) continue;
			double dx = x[i] - meanX;
			double dz = z[i] - meanZ;
			xx += dx * dx;
			xz += dx * dz;
			zz += dz * dz;
		}
		// The main axis of the cloth's spread over the ground.
		double angle = 0.5 * Math.atan2(2 * xz, xx - zz);
		float acrossX = (float) Math.cos(angle);
		float acrossZ = (float) Math.sin(angle);
		// Pointed the same way each frame, so the picture does not flip as the sail swings.
		if (acrossX < -1e-6f || (acrossX <= 1e-6f && acrossZ < 0))
		{
			acrossX = -acrossX;
			acrossZ = -acrossZ;
		}

		float minU = Float.MAX_VALUE, maxU = -Float.MAX_VALUE;
		float minV = Float.MAX_VALUE, maxV = -Float.MAX_VALUE;
		for (int i = 0; i < vertexCount; i++)
		{
			if (!inCloth[i]) continue;
			u[i] = (float) ((x[i] - meanX) * acrossX + (z[i] - meanZ) * acrossZ);
			v[i] = y[i];
			minU = Math.min(minU, u[i]);
			maxU = Math.max(maxU, u[i]);
			minV = Math.min(minV, v[i]);
			maxV = Math.max(maxV, v[i]);
		}
		float width = maxU - minU;
		float height = maxV - minV;
		for (int i = 0; i < vertexCount; i++)
		{
			if (!inCloth[i]) continue;
			u[i] = width > 0 ? (u[i] - minU) / width : 0.5f;
			v[i] = height > 0 ? (v[i] - minV) / height : 0.5f;
		}
	}

	/**
	 * Reads the game's lighting back out of the lit colours: each corner's lightness against the
	 * face's unlit lightness. {@link #shadeScale()} later evens it out for the side in view.
	 */
	private void shade(int[] colours1, int[] colours2, int[] colours3, short[] unlitColours, short[] textures)
	{
		for (int f = 0; f < faceCount; f++)
		{
			if (kind[f] != CLOTH) continue;
			int first = colours1[f];
			int second = colours2[f];
			int third = colours3[f];
			if (third == -1)
			{
				second = first;
				third = first;
			}
			boolean textured = textures != null && textures[f] != -1;
			// Textured faces keep only a lightness, around the middle of the range.
			float base = textured ? 64 : unlitColours != null ? Math.max(8, unlitColours[f] & 0x7f) : 64;
			shade[f * 3] = (first & 0x7f) / base;
			shade[f * 3 + 1] = (second & 0x7f) / base;
			shade[f * 3 + 2] = (third & 0x7f) / base;
		}
	}

	private float modelArea(int face)
	{
		int i = a[face], j = b[face], k = c[face];
		float ux = x[j] - x[i], uy = y[j] - y[i], uz = z[j] - z[i];
		float wx = x[k] - x[i], wy = y[k] - y[i], wz = z[k] - z[i];
		float nx = uy * wz - uz * wy;
		float ny = uz * wx - ux * wz;
		float nz = ux * wy - uy * wx;
		return (float) Math.sqrt(nx * nx + ny * ny + nz * nz) / 2;
	}

	private void allocate(int vertices, int faces)
	{
		if (x.length < vertices)
		{
			int size = Math.max(vertices, x.length * 2);
			x = new float[size];
			y = new float[size];
			z = new float[size];
			u = new float[size];
			v = new float[size];
			screenX = new float[size];
			screenY = new float[size];
			inverseDepth = new float[size];
			inCloth = new boolean[size];
		}
		if (a.length < faces)
		{
			int size = Math.max(faces, a.length * 2);
			a = new int[size];
			b = new int[size];
			c = new int[size];
			kind = new byte[size];
			shade = new float[size * 3];
			faceColour = new int[size];
			faceArea = new float[size];
		}
	}
}

package com.sailpainter;

import com.google.common.collect.ImmutableSet;
import java.util.Set;
import net.runelite.api.gameval.ObjectID;

/** The sail cloth objects a player boat can carry: one per hull size and sail colour. */
final class SailObjects
{
	private static final Set<Integer> IDS = ImmutableSet.of(
		// Raft
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_1X3_LINEN,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_1X3_CANVAS,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_1X3_COTTON,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_1X3_BLACK,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_1X3_YELLOW,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_1X3_PURPLE,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_1X3_GREEN,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_1X3_BLUE,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_1X3_PINK,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_1X3_RED,
		// Skiff
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_2X5_LINEN,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_2X5_CANVAS,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_2X5_COTTON,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_2X5_BLACK,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_2X5_YELLOW,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_2X5_PURPLE,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_2X5_GREEN,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_2X5_BLUE,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_2X5_PINK,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_2X5_RED,
		// Sloop
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_3X8_LINEN,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_3X8_CANVAS,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_3X8_COTTON,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_3X8_BLACK,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_3X8_YELLOW,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_3X8_PURPLE,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_3X8_GREEN,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_3X8_BLUE,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_3X8_PINK,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_3X8_RED,
		ObjectID.SAILING_BOAT_SAIL_KANDARIN_3X8_PIRATE
	);

	private SailObjects()
	{
	}

	static boolean isSail(int id)
	{
		return IDS.contains(id);
	}
}

package com.sailpainter;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.WeakHashMap;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Model;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.Projection;
import net.runelite.api.Renderable;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Draws the design over the sail of your boat each frame. The game gives no way to change what a
 * sail looks like, so this renders the sail again on top: it projects the sail's own model the way
 * the client does, works out which pixels of cloth nothing on the boat is in front of, and paints
 * the picture across those.
 */
class SailOverlay extends Overlay implements Projector
{
	/** Vertices closer to the camera than this cannot be placed on screen; the client uses the same limit. */
	private static final float NEAR = 50;
	private static final Color DEBUG_SAIL = new Color(80, 255, 120);
	private static final Color DEBUG_OTHER = Color.WHITE;

	private final Client client;
	private final SailPainterPlugin plugin;
	private final SailPainterConfig config;
	private final SailRaster raster = new SailRaster();
	private final List<SailMesh> meshes = new ArrayList<>();
	private final List<GameObject> sails = new ArrayList<>();
	private final float[] point = new float[4];
	private final float[] bounds = new float[4];
	/** Where the picture was fitted on each sail last frame, so it can be held steady. */
	private final Map<GameObject, float[]> fits = new WeakHashMap<>();
	private float[] occluderX = new float[0];
	private float[] occluderY = new float[0];
	private float[] occluderDepth = new float[0];

	// This frame's camera, for the boat being drawn.
	private Projection projection;
	private float centreX;
	private float centreY;
	private float scale;

	@Inject
	SailOverlay(Client client, SailPainterPlugin plugin, SailPainterConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		// Drawn first, so other plugins' markers stay on top of the picture.
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		boolean paintMine = config.paintSail();
		boolean debug = config.debug();
		if (!paintMine && !debug && !config.showPartySails())
		{
			plugin.reportStatus(SailPainterPlugin.Status.OFF);
			return null;
		}
		boolean wholeModel = config.paintArea() == PaintArea.WHOLE_MODEL;
		boolean fit = config.fit() == PictureFit.FIT;

		int viewX = client.getViewportXOffset();
		int viewY = client.getViewportYOffset();
		int viewWidth = client.getViewportWidth();
		int viewHeight = client.getViewportHeight();
		centreX = viewWidth / 2f + viewX;
		centreY = viewHeight / 2f + viewY;
		scale = client.getScale();

		// The status is about your own sail; party members' boats are painted without reporting on them.
		SailPainterPlugin.Status status = SailPainterPlugin.Status.NO_BOAT;
		for (SailPainterPlugin.Boat boat : plugin.boats())
		{
			WorldView view = boat.view;
			Design design = boat.design;
			boolean paint = !boat.mine || paintMine;
			projection = view.getCanvasProjection();
			if (projection == null) continue;
			Collection<GameObject> objects = plugin.objectsOn(view.getId());

			sails.clear();
			for (GameObject object : objects)
			{
				if (SailObjects.isSail(shownId(object))) sails.add(object);
				else if (debug) label(graphics, object, describe(object), DEBUG_OTHER);
			}
			if (sails.isEmpty())
			{
				if (boat.mine) status = better(status, SailPainterPlugin.Status.NO_SAIL);
				continue;
			}
			if (paint && design.isBlank())
			{
				if (boat.mine) status = better(status, SailPainterPlugin.Status.BLANK);
				if (!debug) continue;
			}

			// Each sail is copied out before any other model is fetched, since animated models share a buffer.
			int count = 0;
			bounds[0] = bounds[1] = Float.MAX_VALUE;
			bounds[2] = bounds[3] = -Float.MAX_VALUE;
			for (GameObject sail : sails)
			{
				SailMesh mesh = mesh(count);
				boolean prepared = prepare(sail, mesh, wholeModel, fit);
				if (debug) label(graphics, sail, describe(sail) + " sail, cloth " + (prepared ? mesh.clothFaces : 0) + "/" + mesh.faceCount, DEBUG_SAIL);
				if (prepared && mesh.addClothBounds(bounds)) count++;
			}

			if (!paint || design.isBlank()) continue;
			int left = Math.max(viewX, (int) Math.floor(bounds[0]));
			int top = Math.max(viewY, (int) Math.floor(bounds[1]));
			int right = Math.min(viewX + viewWidth, (int) Math.ceil(bounds[2]) + 1);
			int bottom = Math.min(viewY + viewHeight, (int) Math.ceil(bounds[3]) + 1);
			if (count == 0 || left >= right || top >= bottom)
			{
				if (boat.mine) status = better(status, SailPainterPlugin.Status.NOT_IN_VIEW);
				continue;
			}

			raster.begin(left, top, right - left, bottom - top);
			raster.setPicture(design, config.opacity() * 255 / 100, config.shading() / 100f, config.smooth());
			for (int i = 0; i < count; i++) meshes.get(i).occlude(raster);
			if (config.occlusion())
			{
				occludeObjects(objects);
				occludeActors(view);
			}
			boolean readable = config.readableBothSides();
			for (int i = 0; i < count; i++)
			{
				SailMesh mesh = meshes.get(i);
				mesh.paint(raster, readable && mesh.mirrored());
			}
			graphics.drawImage(raster.image(), left, top, right, bottom, 0, 0, right - left, bottom - top, null);
			if (boat.mine) status = SailPainterPlugin.Status.PAINTING;
		}
		plugin.reportStatus(paintMine ? status : SailPainterPlugin.Status.OFF);
		return null;
	}

	@Override
	public void project(int count, float[] x, float[] y, float[] z, int localX, int localY, int localZ, int orientation,
		float[] screenX, float[] screenY, float[] inverseDepth)
	{
		orientation &= 2047;
		float sin = Perspective.SINE[orientation] / 65536f;
		float cos = Perspective.COSINE[orientation] / 65536f;
		for (int i = 0; i < count; i++)
		{
			// Turned about the vertical the same way the client turns a model before placing it.
			float across = x[i];
			float along = z[i];
			if (orientation != 0)
			{
				float turned = across * cos + along * sin;
				along = along * cos - across * sin;
				across = turned;
			}
			projection.project(across + localX, y[i] + localZ, along + localY, point);
			float distance = point[2];
			if (distance < NEAR)
			{
				inverseDepth[i] = 0;
				continue;
			}
			screenX[i] = centreX + point[0] * scale / distance;
			screenY[i] = centreY + point[1] * scale / distance;
			inverseDepth[i] = 1 / distance;
		}
	}

	private boolean prepare(GameObject sail, SailMesh mesh, boolean wholeModel, boolean fit)
	{
		Renderable renderable = sail.getRenderable();
		Model model = modelOf(renderable);
		if (model == null)
		{
			mesh.faceCount = 0;
			return false;
		}
		mesh.build(model.getVerticesCount(), model.getVerticesX(), model.getVerticesY(), model.getVerticesZ(),
			model.getFaceCount(), model.getFaceIndices1(), model.getFaceIndices2(), model.getFaceIndices3(),
			model.getFaceColors1(), model.getFaceColors2(), model.getFaceColors3(),
			model.getUnlitFaceColors(), model.getFaceTextures(), model.getFaceTransparencies(), wholeModel);
		if (mesh.clothFaces == 0) return false;
		if (fit) mesh.fitInside(fits.computeIfAbsent(sail, key -> new float[4]));
		else mesh.stretch();
		mesh.project(this, sail.getX(), sail.getY(), sail.getZ() - renderable.getAnimationHeightOffset(), sail.getModelOrientation());
		return true;
	}

	/** Everything else on the boat goes into the depth buffer, so the mast and the rest can stand in front of the sail. */
	private void occludeObjects(Collection<GameObject> objects)
	{
		for (GameObject object : objects)
		{
			if (sails.contains(object)) continue;
			Renderable renderable = object.getRenderable();
			Model model = modelOf(renderable);
			if (model == null) continue;
			occludeModel(model, object.getX(), object.getY(), object.getZ() - renderable.getAnimationHeightOffset(), object.getModelOrientation());
		}
	}

	/** You, your crew and anyone else aboard. */
	private void occludeActors(WorldView boat)
	{
		Player me = client.getLocalPlayer();
		boolean meSeen = false;
		for (Player player : boat.players())
		{
			if (player == null) continue;
			meSeen |= player == me;
			occludeActor(player, boat);
		}
		for (NPC npc : boat.npcs())
		{
			if (npc != null) occludeActor(npc, boat);
		}
		if (me != null && !meSeen) occludeActor(me, boat);
	}

	private void occludeActor(Actor actor, WorldView boat)
	{
		WorldView view = actor.getWorldView();
		if (view == null || view.getId() != boat.getId()) return;
		LocalPoint location = actor.getLocalLocation();
		if (location == null) return;
		Model model = actor.getModel();
		if (model == null) return;
		int z = Perspective.getFootprintTileHeight(client, location, boat.getPlane(), actor.getFootprintSize()) - actor.getAnimationHeightOffset();
		occludeModel(model, location.getX(), location.getY(), z, actor.getCurrentOrientation());
	}

	private void occludeModel(Model model, int localX, int localY, int localZ, int orientation)
	{
		int vertices = model.getVerticesCount();
		if (occluderX.length < vertices)
		{
			int size = Math.max(vertices, occluderX.length * 2);
			occluderX = new float[size];
			occluderY = new float[size];
			occluderDepth = new float[size];
		}
		project(vertices, model.getVerticesX(), model.getVerticesY(), model.getVerticesZ(), localX, localY, localZ, orientation, occluderX, occluderY, occluderDepth);

		int[] f1 = model.getFaceIndices1();
		int[] f2 = model.getFaceIndices2();
		int[] f3 = model.getFaceIndices3();
		int[] colours3 = model.getFaceColors3();
		byte[] transparencies = model.getFaceTransparencies();
		for (int f = 0, faces = model.getFaceCount(); f < faces; f++)
		{
			if (colours3[f] == -2) continue;
			if (transparencies != null && (transparencies[f] & 0xff) >= SailMesh.SEE_THROUGH) continue;
			int i = f1[f], j = f2[f], k = f3[f];
			float zi = occluderDepth[i], zj = occluderDepth[j], zk = occluderDepth[k];
			if (zi <= 0 || zj <= 0 || zk <= 0) continue;
			float xi = occluderX[i], xj = occluderX[j], xk = occluderX[k];
			float yi = occluderY[i], yj = occluderY[j], yk = occluderY[k];
			// The game only draws faces turned towards the camera.
			if ((xj - xi) * (yk - yi) - (yj - yi) * (xk - xi) >= 0) continue;
			raster.occlude(xi, yi, zi, xj, yj, zj, xk, yk, zk);
		}
	}

	private SailMesh mesh(int index)
	{
		while (meshes.size() <= index) meshes.add(new SailMesh());
		return meshes.get(index);
	}

	/** The object's ID, or for one that changes with game state, the ID it is showing as now. */
	private int shownId(GameObject object)
	{
		int id = object.getId();
		ObjectComposition definition = client.getObjectDefinition(id);
		if (definition == null || definition.getImpostorIds() == null) return id;
		ObjectComposition shown = definition.getImpostor();
		return shown == null ? -1 : shown.getId();
	}

	private String describe(GameObject object)
	{
		int shown = shownId(object);
		return shown == object.getId() ? String.valueOf(shown) : object.getId() + ">" + shown;
	}

	private static void label(Graphics2D graphics, GameObject object, String text, Color color)
	{
		Point location = object.getCanvasLocation();
		if (location != null) OverlayUtil.renderTextLocation(graphics, location, text, color);
	}

	private static Model modelOf(Renderable renderable)
	{
		if (renderable == null) return null;
		return renderable instanceof Model ? (Model) renderable : renderable.getModel();
	}

	private static SailPainterPlugin.Status better(SailPainterPlugin.Status current, SailPainterPlugin.Status candidate)
	{
		return candidate.ordinal() > current.ordinal() ? candidate : current;
	}
}

package com.sailpainter;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(SailPainterConfig.GROUP)
public interface SailPainterConfig extends Config
{
	String GROUP = "sailpainter";

	@ConfigSection(name = "Party", description = "Sharing sails with friends in your RuneLite party", position = 9)
	String party = "party";

	@ConfigItem(keyName = "shareWithParty", name = "Share with party", description = "Send your design to the people in your RuneLite party who also have Sail Painter, so they see it on your boat. Join a party from RuneLite's Party panel", section = party, position = 0)
	default boolean shareWithParty()
	{
		return false;
	}

	@ConfigItem(keyName = "showPartySails", name = "Show party sails", description = "Paint the sails of party members who share their design, on whichever boat they are aboard", section = party, position = 1)
	default boolean showPartySails()
	{
		return true;
	}

	@ConfigSection(name = "Troubleshooting", description = "For when the picture does not land where it should", position = 10, closedByDefault = true)
	String troubleshooting = "troubleshooting";

	@ConfigItem(keyName = "paintSail", name = "Paint my sail", description = "Show your picture on the sail of your own boat, or of the boat you are aboard. Only you can see it", position = 0)
	default boolean paintSail()
	{
		return true;
	}

	@ConfigItem(keyName = "readableBothSides", name = "Readable from both sides", description = "Show the picture the right way round from behind the sail as well. Turn off to see it mirrored from behind, like paint showing through the cloth", position = 1)
	default boolean readableBothSides()
	{
		return true;
	}

	@ConfigItem(keyName = "fit", name = "Picture", description = "Fit inside the sail: the whole picture in the biggest box that fits on the cloth, so a triangular sail loses none of it. Stretch over the sail: the picture covers all the cloth, and a triangular sail cuts off its corners", position = 2)
	default PictureFit fit()
	{
		return PictureFit.FIT;
	}

	@ConfigItem(keyName = "opacity", name = "Opacity", description = "How solid the picture is. Lower lets the sail's own colour show through", position = 3)
	@Units(Units.PERCENT)
	@Range(min = 10, max = 100)
	default int opacity()
	{
		return 100;
	}

	@ConfigItem(keyName = "shading", name = "Shading", description = "How much of the sail's own light and shadow falls on the picture, so that it follows the folds of the cloth", position = 4)
	@Units(Units.PERCENT)
	@Range(max = 100)
	default int shading()
	{
		return 70;
	}

	@ConfigItem(keyName = "occlusion", name = "Hide behind crew and rigging", description = "Let people and parts of the boat in front of the sail cover the picture", position = 5)
	default boolean occlusion()
	{
		return true;
	}

	@ConfigItem(keyName = "smooth", name = "Smooth picture", description = "Blend between the picture's pixels rather than keeping them sharp. Suits imported photos more than pixel art", position = 6)
	default boolean smooth()
	{
		return false;
	}

	@ConfigItem(keyName = "paintArea", name = "Paint", description = "Sail cloth: only the cloth, leaving ropes and spars alone. Whole sail model: everything the sail is made of, if the cloth is not being picked out properly", section = troubleshooting, position = 0)
	default PaintArea paintArea()
	{
		return PaintArea.CLOTH;
	}

	@ConfigItem(keyName = "debug", name = "Show debug info", description = "Label every object on your boat with its ID, and the sail with how much of it is being painted", section = troubleshooting, position = 1)
	default boolean debug()
	{
		return false;
	}
}

package com.sailpainter;

import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * A party member's sail design, sent to the rest of the party through RuneLite's party service.
 * The class name is the message's type on the wire, so it is kept specific to this plugin.
 */
public class SailPainterDesign extends PartyMemberMessage
{
	/** The sender's in-game name, which is how their boat is told apart. */
	private final String name;
	/** The design as base64 PNG, or null when the sender stops sharing. */
	private final String png;

	public SailPainterDesign(String name, String png)
	{
		this.name = name;
		this.png = png;
	}

	public String getName()
	{
		return name;
	}

	public String getPng()
	{
		return png;
	}

	// The party service logs every message it sends and receives; the picture itself would swamp the log.
	@Override
	public String toString()
	{
		return "SailPainterDesign(member=" + getMemberId() + ", name=" + name + ", characters=" + (png == null ? 0 : png.length()) + ")";
	}
}

package com.sailpainter;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.Timer;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/** The sidebar: what is on the sail now, whether it is being painted, and the way into the studio. */
class SailPainterPanel extends PluginPanel
{
	private static final int STATUS_MS = 500;
	private static final int PREVIEW = PANEL_WIDTH - 20;

	private final SailPainterPlugin plugin;
	private final Preview preview = new Preview();
	private final JLabel status = new JLabel();
	private final JLabel party = new JLabel();
	private final Timer timer;

	SailPainterPanel(SailPainterPlugin plugin)
	{
		super(false);
		this.plugin = plugin;
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel title = new JLabel("Sail Painter");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		content.add(left(title));
		content.add(Box.createVerticalStrut(8));
		content.add(left(preview));
		content.add(Box.createVerticalStrut(8));
		status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		content.add(left(status));
		party.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		party.setBorder(BorderFactory.createEmptyBorder(6, 0, 0, 0));
		content.add(left(party));
		content.add(Box.createVerticalStrut(10));

		JButton studio = new JButton("Open drawing studio");
		studio.addActionListener(event -> plugin.openStudio());
		JButton open = new JButton("Import picture…");
		open.addActionListener(event ->
		{
			BufferedImage image = DesignFiles.open(this);
			if (image != null) plugin.importPicture(image, this);
		});
		JButton save = new JButton("Export picture…");
		save.addActionListener(event -> DesignFiles.save(this, plugin.getDesign()));
		JButton clear = new JButton("Clear sail");
		clear.addActionListener(event ->
		{
			if (JOptionPane.showConfirmDialog(this, "Rub out the whole picture?", "Sail Painter", JOptionPane.YES_NO_OPTION) == JOptionPane.YES_OPTION)
			{
				plugin.clearDesign(this);
			}
		});
		JPanel buttons = new JPanel(new GridLayout(0, 1, 0, 6));
		buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
		buttons.add(studio);
		buttons.add(open);
		buttons.add(save);
		buttons.add(clear);
		content.add(left(buttons));
		content.add(Box.createVerticalStrut(12));

		JLabel note = new JLabel(html("Only you can see your painted sail, unless you share it with your RuneLite party. Settings are under Sail Painter in the configuration panel."));
		note.setFont(FontManager.getRunescapeSmallFont());
		note.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		content.add(left(note));

		add(content, BorderLayout.NORTH);
		designChanged(plugin.getDesign());
		showStatus();
		timer = new Timer(STATUS_MS, event -> showStatus());
		timer.start();
	}

	void designChanged(Design design)
	{
		preview.setDesign(design);
	}

	void stop()
	{
		timer.stop();
	}

	private void showStatus()
	{
		status.setText(html(plugin.getStatus().text));
		String partyText = plugin.partyText();
		party.setText(partyText == null ? "" : html(partyText));
		party.setVisible(partyText != null);
	}

	private static String html(String text)
	{
		// Swing's HTML measures widths larger than the pixels they end up taking, so this is smaller than the space.
		return "<html><div style='width:" + (PREVIEW * 3 / 4) + "px'>" + text + "</div></html>";
	}

	private static JComponent left(JComponent component)
	{
		component.setAlignmentX(Component.LEFT_ALIGNMENT);
		return component;
	}

	/** The design as it stands, over a checkerboard where the plain sail will show. */
	private static class Preview extends JComponent
	{
		private static final int CHECKER = 8;
		private Design design;
		private BufferedImage image;

		Preview()
		{
			Dimension size = new Dimension(PREVIEW, PREVIEW);
			setPreferredSize(size);
			setMinimumSize(size);
			setMaximumSize(size);
		}

		void setDesign(Design design)
		{
			this.design = design;
			this.image = design.toImage();
			repaint();
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			try
			{
				int size = Math.min(getWidth(), getHeight());
				for (int y = 0; y < size; y += CHECKER)
				{
					for (int x = 0; x < size; x += CHECKER)
					{
						g.setColor(((x + y) / CHECKER) % 2 == 0 ? ColorScheme.MEDIUM_GRAY_COLOR : ColorScheme.DARKER_GRAY_COLOR);
						g.fillRect(x, y, CHECKER, CHECKER);
					}
				}
				if (design == null) return;
				if (design.isBlank())
				{
					String text = "Nothing drawn yet";
					g.setFont(FontManager.getRunescapeFont());
					int width = g.getFontMetrics().stringWidth(text);
					g.setColor(ColorScheme.DARKER_GRAY_COLOR);
					g.fillRect((size - width) / 2 - 6, size / 2 - 14, width + 12, 22);
					g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
					g.drawString(text, (size - width) / 2, size / 2 + 2);
					return;
				}
				g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
				g.drawImage(image, 0, 0, size, size, null);
				g.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
				g.drawRect(0, 0, size - 1, size - 1);
			}
			finally
			{
				g.dispose();
			}
		}
	}
}

package com.sailpainter;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WorldViewLoaded;
import net.runelite.api.events.WorldViewUnloaded;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PartyChanged;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.party.events.UserJoin;
import net.runelite.client.party.events.UserPart;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Sail Painter",
	description = "Draw a picture and see it on your boat's sail",
	tags = {"sailing", "sail", "boat", "ship", "paint", "draw", "custom", "cosmetic", "pixel art", "party"},
	internalName = "sail-painter"
)
public class SailPainterPlugin extends Plugin
{
	static final int DEFAULT_SIZE = 128;
	/** Imported pictures are shrunk to fit this; a sail rarely covers more screen than that. */
	static final int IMPORT_SIZE = 256;
	private static final long SAVE_DELAY_MS = 750;
	/** The overlay reports in every frame; a report older than this means it is not running. */
	private static final long STATUS_STALE_MS = 2000;

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private SailPainterConfig config;
	@Inject private OverlayManager overlayManager;
	@Inject private SailOverlay overlay;
	@Inject private ClientToolbar clientToolbar;
	@Inject private ScheduledExecutorService executor;
	@Inject private PartyService partyService;
	@Inject private WSClient wsClient;

	private DesignStore store;
	/** Whether the party was last told about a design, so that it can be told when that stops. */
	private volatile boolean shared;

	// Client thread state.
	/** Every object standing on a boat, by the boat's world view, kept up from spawn events. */
	private final Map<Integer, Set<GameObject>> boatObjects = new HashMap<>();
	private final List<Boat> boats = new ArrayList<>();
	private final List<Boat> boatPool = new ArrayList<>();

	// Swing thread state.
	private SailPainterPanel panel;
	private StudioWindow studio;
	private NavigationButton navigationButton;

	// Shared.
	private volatile Design design = Design.blank(DEFAULT_SIZE, DEFAULT_SIZE);
	private volatile Status status = Status.NO_BOAT;
	private volatile long statusAt;
	private volatile String localName;
	/** Designs shared by other party members, by member. Filled from the party connection's thread. */
	private final Map<Long, PartyDesign> partyDesigns = new ConcurrentHashMap<>();
	private ScheduledFuture<?> pendingSave;

	/** A boat to paint and the design that goes on it. */
	static final class Boat
	{
		WorldView view;
		Design design;
		/** Yours, or the one you are aboard, rather than a party member's. */
		boolean mine;
	}

	private static final class PartyDesign
	{
		/** The sender's in-game name, standardised for comparing. */
		final String name;
		final Design design;

		PartyDesign(String name, Design design)
		{
			this.name = name;
			this.design = design;
		}
	}

	/** What the overlay last found. With more than one boat, the later of the first five wins. */
	enum Status
	{
		NO_BOAT("Board your boat, or go near it, to see your sail painted."),
		NO_SAIL("Your boat is here, but its sail was not recognised. Turn on Show debug info in the settings to see the IDs on board."),
		BLANK("Your boat is here. Draw something to paint its sail."),
		NOT_IN_VIEW("Your sail is out of view."),
		PAINTING("Painting your sail."),
		OFF("Painting is switched off in the settings."),
		LOGGED_OUT("Log in and board your boat to see your sail painted.");

		final String text;

		Status(String text)
		{
			this.text = text;
		}
	}

	@Provides
	SailPainterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SailPainterConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		panel = new SailPainterPanel(this);
		navigationButton = NavigationButton.builder()
			.tooltip("Sail Painter")
			.icon(ImageUtil.loadImageResource(getClass(), "panel_icon.png"))
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);
		wsClient.registerMessage(SailPainterDesign.class);
		executor.execute(this::loadDesign);
		clientThread.invokeLater(this::scanAll);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		clientToolbar.removeNavigation(navigationButton);
		flushSave();
		// Tell the party this sail is going plain while the message type is still known, then stop listening.
		// Sending nothing needs no encoding, and the send itself only queues.
		share(false);
		wsClient.unregisterMessage(SailPainterDesign.class);
		partyDesigns.clear();
		clientThread.invoke(boatObjects::clear);
		SailPainterPanel oldPanel = panel;
		StudioWindow oldStudio = studio;
		panel = null;
		studio = null;
		navigationButton = null;
		SwingUtilities.invokeLater(() ->
		{
			if (oldPanel != null) oldPanel.stop();
			if (oldStudio != null) oldStudio.dispose();
		});
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		track(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		GameObject object = event.getGameObject();
		WorldView view = object.getWorldView();
		if (view != null)
		{
			Set<GameObject> objects = boatObjects.get(view.getId());
			if (objects != null) objects.remove(object);
			return;
		}
		for (Set<GameObject> objects : boatObjects.values()) objects.remove(object);
	}

	@Subscribe
	public void onWorldViewLoaded(WorldViewLoaded event)
	{
		WorldView view = event.getWorldView();
		if (view.isTopLevel()) return;
		// Objects already on the boat when it loads might not each be announced, so look once it has settled.
		clientThread.invokeLater(() ->
		{
			if (client.getWorldView(view.getId()) == view) scan(view);
		});
	}

	@Subscribe
	public void onWorldViewUnloaded(WorldViewUnloaded event)
	{
		boatObjects.remove(event.getWorldView().getId());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			boatObjects.clear();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// The party matches a design to a boat by the sender's name, which is only known once logged in.
		Player me = client.getLocalPlayer();
		String name = me == null ? null : me.getName();
		if (name != null && !name.equals(localName))
		{
			localName = name;
			shareSoon();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!SailPainterConfig.GROUP.equals(event.getGroup())) return;
		if ("shareWithParty".equals(event.getKey())) shareSoon();
	}

	@Subscribe
	public void onPartyChanged(PartyChanged event)
	{
		partyDesigns.clear();
		shareSoon();
	}

	@Subscribe
	public void onUserJoin(UserJoin event)
	{
		// Someone new: they need this design too. Joining ourselves comes as a join as well.
		shareSoon();
	}

	@Subscribe
	public void onUserPart(UserPart event)
	{
		partyDesigns.remove(event.getMemberId());
	}

	/** Party connection thread. Another member's design, or word that they stopped sharing it. */
	@Subscribe
	public void onSailPainterDesign(SailPainterDesign message)
	{
		PartyMember local = partyService.getLocalMember();
		if (local != null && local.getMemberId() == message.getMemberId()) return;
		if (message.getName() == null || message.getPng() == null)
		{
			partyDesigns.remove(message.getMemberId());
			return;
		}
		try
		{
			Design received = DesignCodec.unshare(message.getPng());
			partyDesigns.put(message.getMemberId(), new PartyDesign(Text.standardize(message.getName()), received));
		}
		catch (IOException e)
		{
			log.debug("Ignoring an unreadable sail design from party member {}", message.getMemberId(), e);
		}
	}

	/**
	 * Client thread. The boats to paint and what goes on each: your design on your own boat, a party
	 * member's on the boat they are aboard if they share theirs, and yours on any other boat you are
	 * aboard.
	 */
	List<Boat> boats()
	{
		boats.clear();
		WorldView top = client.getTopLevelWorldView();
		if (top == null) return boats;
		Player me = client.getLocalPlayer();
		WorldView aboard = me == null ? null : me.getWorldView();
		if (aboard != null && aboard.isTopLevel()) aboard = null;
		boolean showParty = config.showPartySails() && !partyDesigns.isEmpty();

		boolean aboardSeen = false;
		for (WorldEntity entity : top.worldEntities())
		{
			WorldView view = entity.getWorldView();
			if (view == null) continue;
			boolean isAboard = aboard != null && view.getId() == aboard.getId();
			aboardSeen |= isAboard;
			// The game hides a boat that overlaps another; its sail should vanish with it.
			if (entity.isHiddenForOverlap()) continue;
			if (entity.getOwnerType() == WorldEntity.OWNER_TYPE_SELF_PLAYER)
			{
				addBoat(view, design, true);
				continue;
			}
			Design theirs = showParty ? partyDesignAboard(view, me) : null;
			if (theirs != null) addBoat(view, theirs, false);
			else if (isAboard) addBoat(view, design, true);
		}
		if (aboard != null && !aboardSeen) addBoat(aboard, design, true);
		return boats;
	}

	/** The design of a sharing party member standing on the boat, if any. */
	private Design partyDesignAboard(WorldView view, Player me)
	{
		for (Player player : view.players())
		{
			if (player == null || player == me || player.getName() == null) continue;
			String name = Text.standardize(player.getName());
			for (PartyDesign shared : partyDesigns.values())
			{
				if (shared.name.equals(name)) return shared.design;
			}
		}
		return null;
	}

	private void addBoat(WorldView view, Design design, boolean mine)
	{
		if (boatPool.size() <= boats.size()) boatPool.add(new Boat());
		Boat boat = boatPool.get(boats.size());
		boat.view = view;
		boat.design = design;
		boat.mine = mine;
		boats.add(boat);
	}

	/** Client thread. Everything standing on the boat with the given world view. */
	Collection<GameObject> objectsOn(int worldViewId)
	{
		Set<GameObject> objects = boatObjects.get(worldViewId);
		return objects == null ? Collections.emptySet() : objects;
	}

	Design getDesign()
	{
		return design;
	}

	/**
	 * Any thread. Replaces the design on the sail. Saving is held back briefly so that a stroke
	 * being drawn is written once when it settles rather than on every mouse movement.
	 *
	 * @param source whoever made the change, which is not told about it again
	 */
	void setDesign(Design design, boolean save, Object source)
	{
		this.design = design;
		if (save) scheduleSave();
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null) panel.designChanged(design);
			if (studio != null && source != studio) studio.load(design);
		});
	}

	/** Swing thread. The picture becomes the design, scaled down if it is bigger than a sail can show. */
	void importPicture(BufferedImage image, Object source)
	{
		setDesign(Design.fromImage(image, IMPORT_SIZE), true, source);
	}

	void clearDesign(Object source)
	{
		Design current = design;
		setDesign(Design.blank(current.width(), current.height()), true, source);
	}

	/** Swing thread. */
	void openStudio()
	{
		if (studio == null) studio = new StudioWindow(this);
		studio.load(design);
		studio.setVisible(true);
		studio.toFront();
	}

	SailPainterConfig getConfig()
	{
		return config;
	}

	void reportStatus(Status status)
	{
		this.status = status;
		statusAt = System.currentTimeMillis();
	}

	Status getStatus()
	{
		if (System.currentTimeMillis() - statusAt > STATUS_STALE_MS) return Status.LOGGED_OUT;
		return status;
	}

	private void track(GameObject object)
	{
		WorldView view = object.getWorldView();
		if (view == null || view.isTopLevel()) return;
		boatObjects.computeIfAbsent(view.getId(), id -> Collections.newSetFromMap(new IdentityHashMap<>())).add(object);
	}

	private void scanAll()
	{
		WorldView top = client.getTopLevelWorldView();
		if (top == null) return;
		for (WorldView view : top.worldViews()) scan(view);
	}

	private void scan(WorldView view)
	{
		Scene scene = view.getScene();
		if (scene == null) return;
		for (Tile[][] plane : scene.getTiles())
		{
			if (plane == null) continue;
			for (Tile[] column : plane)
			{
				if (column == null) continue;
				for (Tile tile : column)
				{
					if (tile == null) continue;
					GameObject[] objects = tile.getGameObjects();
					if (objects == null) continue;
					for (GameObject object : objects)
					{
						if (object != null) track(object);
					}
				}
			}
		}
	}

	/** Party status for the panel, or null when there is nothing to say. */
	String partyText()
	{
		int showing = config.showPartySails() ? partyDesigns.size() : 0;
		String received = showing == 0 ? "" : " " + showing + (showing == 1 ? " party member shares" : " party members share") + " their sail with you.";
		if (!config.shareWithParty()) return showing == 0 ? null : received.trim();
		if (!partyService.isInParty()) return "Sharing is on, but you are not in a party. Join one from RuneLite's Party panel." + received;
		return "Your sail is shared with your party." + received;
	}

	/** Executor thread. Loads the saved design from the plugin's own folder. */
	private void loadDesign()
	{
		try
		{
			Design saved = store().load();
			if (saved != null) setDesign(saved, false, null);
		}
		catch (IOException e)
		{
			log.warn("Could not load the saved sail design", e);
		}
	}

	/** Executor thread. The plugin's folder is made on first use, which is disk work. */
	private synchronized DesignStore store() throws IOException
	{
		if (store == null) store = new DesignStore(getPluginDirectory());
		return store;
	}

	/** Sends the design to the party a moment from now, off the thread that asked. */
	private void shareSoon()
	{
		executor.execute(() -> share(config.shareWithParty()));
	}

	/**
	 * Sends the current design to the party, or, when sharing has just been turned off, an empty one
	 * so that it disappears from their screens too. Encoding is work, so turning it on belongs on the executor.
	 */
	private synchronized void share(boolean on)
	{
		if (!partyService.isInParty() || localName == null)
		{
			shared = false;
			return;
		}
		if (!on && !shared) return;
		String png = null;
		Design current = design;
		if (on && !current.isBlank())
		{
			try
			{
				png = DesignCodec.share(current);
			}
			catch (IOException e)
			{
				log.debug("Could not prepare the sail design for the party", e);
				return;
			}
		}
		partyService.send(new SailPainterDesign(localName, png));
		shared = png != null;
	}

	private synchronized void scheduleSave()
	{
		if (pendingSave != null) pendingSave.cancel(false);
		pendingSave = executor.schedule(() ->
		{
			save(design);
			share(config.shareWithParty());
		}, SAVE_DELAY_MS, TimeUnit.MILLISECONDS);
	}

	/** Writes a save that was still waiting, without waiting for it. */
	private synchronized void flushSave()
	{
		if (pendingSave == null || pendingSave.isDone()) return;
		pendingSave.cancel(false);
		pendingSave = null;
		Design latest = design;
		executor.execute(() -> save(latest));
	}

	private void save(Design design)
	{
		try
		{
			store().save(design);
		}
		catch (IOException e)
		{
			log.warn("Could not save the sail design", e);
		}
	}
}

package com.sailpainter;

import java.awt.image.BufferedImage;
import java.awt.image.ColorModel;
import java.awt.image.DataBufferInt;
import java.awt.image.Raster;
import java.awt.image.WritableRaster;
import java.util.Arrays;

/**
 * A small software renderer for one patch of the screen. Things in front of the sail go into the
 * depth buffer first; then the picture is painted over the cloth wherever nothing nearer is in the
 * way, with perspective-correct mapping so it does not swim across large faces.
 *
 * <p>Depth is stored as one over the distance, which is linear across a face on screen. Bigger is nearer.
 */
final class SailRaster
{
	/** The picture may sit this much further away than another surface and still show, so it does not flicker against ropes lying on the cloth. */
	private static final float CLOTH_BIAS = 1.003f;
	/** Lets pixel centres exactly on a shared edge land in at least one face, so seams have no pinholes. */
	private static final float EDGE = -0.0001f;
	private static final float OFF_SLACK = 0.002f;

	private int stride;
	private int capacityHeight;
	private int[] color = new int[0];
	private float[] depth = new float[0];
	private BufferedImage image;

	private int originX;
	private int originY;
	private int width;
	private int height;

	private int[] picture;
	private int pictureWidth;
	private int pictureHeight;
	private int opacity = 255;
	private float shading;
	private boolean smooth;

	/** Clears the patch of screen to draw into, from its top left corner. */
	void begin(int x, int y, int width, int height)
	{
		if (width > stride || height > capacityHeight)
		{
			stride = Math.max(width, stride);
			capacityHeight = Math.max(height, capacityHeight);
			color = new int[stride * capacityHeight];
			depth = new float[stride * capacityHeight];
			image = null;
		}
		originX = x;
		originY = y;
		this.width = width;
		this.height = height;
		for (int row = 0; row < height; row++)
		{
			int start = row * stride;
			Arrays.fill(color, start, start + width, 0);
			Arrays.fill(depth, start, start + width, 0);
		}
	}

	void setPicture(Design design, int opacity, float shading, boolean smooth)
	{
		this.picture = design.pixels();
		this.pictureWidth = design.width();
		this.pictureHeight = design.height();
		this.opacity = opacity;
		this.shading = shading;
		this.smooth = smooth;
	}

	int originX()
	{
		return originX;
	}

	int originY()
	{
		return originY;
	}

	int width()
	{
		return width;
	}

	int height()
	{
		return height;
	}

	/** The painted pixels; only the top left {@link #width()} by {@link #height()} is this frame's. */
	BufferedImage image()
	{
		if (image == null)
		{
			DataBufferInt buffer = new DataBufferInt(color, color.length);
			WritableRaster raster = Raster.createPackedRaster(buffer, stride, capacityHeight, stride,
				new int[]{0xff0000, 0xff00, 0xff, 0xff000000}, null);
			image = new BufferedImage(ColorModel.getRGBdefault(), raster, false, null);
		}
		return image;
	}

	/** The painted colour at a screen position, for tests. */
	int colorAt(int x, int y)
	{
		return color[(y - originY) * stride + (x - originX)];
	}

	/** Records a surface in front of the sail without painting anything. */
	void occlude(float x0, float y0, float z0, float x1, float y1, float z1, float x2, float y2, float z2)
	{
		triangle(x0, y0, z0, 0, 0, 0, x1, y1, z1, 0, 0, 0, x2, y2, z2, 0, 0, 0, false);
	}

	/** Paints the picture over a cloth face, where u and v place each corner on the picture and s is how lit it is. */
	void paint(float x0, float y0, float z0, float u0, float v0, float s0,
		float x1, float y1, float z1, float u1, float v1, float s1,
		float x2, float y2, float z2, float u2, float v2, float s2)
	{
		triangle(x0, y0, z0, u0, v0, s0, x1, y1, z1, u1, v1, s1, x2, y2, z2, u2, v2, s2, true);
	}

	private void triangle(float x0, float y0, float z0, float u0, float v0, float s0,
		float x1, float y1, float z1, float u1, float v1, float s1,
		float x2, float y2, float z2, float u2, float v2, float s2, boolean paint)
	{
		float area = (x1 - x0) * (y2 - y0) - (y1 - y0) * (x2 - x0);
		if (area == 0 || Float.isNaN(area) || Float.isInfinite(area)) return;

		int minX = Math.max(originX, (int) Math.floor(Math.min(x0, Math.min(x1, x2))));
		int maxX = Math.min(originX + width - 1, (int) Math.ceil(Math.max(x0, Math.max(x1, x2))));
		int minY = Math.max(originY, (int) Math.floor(Math.min(y0, Math.min(y1, y2))));
		int maxY = Math.min(originY + height - 1, (int) Math.ceil(Math.max(y0, Math.max(y1, y2))));
		if (minX > maxX || minY > maxY) return;

		// Barycentric weights of each corner at the first pixel centre, and how they change per pixel.
		float inverseArea = 1 / area;
		float px = minX + 0.5f;
		float py = minY + 0.5f;
		float w0Row = ((x2 - x1) * (py - y1) - (y2 - y1) * (px - x1)) * inverseArea;
		float w1Row = ((x0 - x2) * (py - y2) - (y0 - y2) * (px - x2)) * inverseArea;
		float w2Row = ((x1 - x0) * (py - y0) - (y1 - y0) * (px - x0)) * inverseArea;
		float w0dx = -(y2 - y1) * inverseArea;
		float w1dx = -(y0 - y2) * inverseArea;
		float w2dx = -(y1 - y0) * inverseArea;
		float w0dy = (x2 - x1) * inverseArea;
		float w1dy = (x0 - x2) * inverseArea;
		float w2dy = (x1 - x0) * inverseArea;

		// u and v are spread evenly over the sail, not the screen, so they are carried over depth.
		float u0z = u0 * z0, u1z = u1 * z1, u2z = u2 * z2;
		float v0z = v0 * z0, v1z = v1 * z1, v2z = v2 * z2;

		for (int y = minY; y <= maxY; y++)
		{
			float w0 = w0Row;
			float w1 = w1Row;
			float w2 = w2Row;
			int index = (y - originY) * stride + (minX - originX);
			for (int x = minX; x <= maxX; x++, index++, w0 += w0dx, w1 += w1dx, w2 += w2dx)
			{
				if (w0 < EDGE || w1 < EDGE || w2 < EDGE) continue;
				float inverseDepth = w0 * z0 + w1 * z1 + w2 * z2;
				if (!paint)
				{
					if (inverseDepth > depth[index]) depth[index] = inverseDepth;
					continue;
				}
				if (inverseDepth * CLOTH_BIAS < depth[index]) continue;
				depth[index] = inverseDepth;
				float u = (w0 * u0z + w1 * u1z + w2 * u2z) / inverseDepth;
				float v = (w0 * v0z + w1 * v1z + w2 * v2z) / inverseDepth;
				// Transparent parts of the picture still claim the pixel, so cloth further back cannot show through them.
				color[index] = light(smooth ? blended(u, v) : nearest(u, v), w0 * s0 + w1 * s1 + w2 * s2);
			}
			w0Row += w0dy;
			w1Row += w1dy;
			w2Row += w2dy;
		}
	}

	private int light(int argb, float shade)
	{
		int alpha = argb >>> 24;
		if (alpha == 0) return 0;
		alpha = alpha * opacity / 255;
		float brightness = 1 + (shade - 1) * shading;
		int red = channel(((argb >> 16) & 0xff) * brightness);
		int green = channel(((argb >> 8) & 0xff) * brightness);
		int blue = channel((argb & 0xff) * brightness);
		return alpha << 24 | red << 16 | green << 8 | blue;
	}

	private static int channel(float value)
	{
		return value >= 255 ? 255 : value <= 0 ? 0 : (int) (value + 0.5f);
	}

	/** Cloth outside the picture, where a fitted picture leaves the sail plain. The slack covers rounding at the picture's edges. */
	private static boolean offPicture(float u, float v)
	{
		return u < -OFF_SLACK || u > 1 + OFF_SLACK || v < -OFF_SLACK || v > 1 + OFF_SLACK;
	}

	private int nearest(float u, float v)
	{
		if (offPicture(u, v)) return 0;
		int x = clamp((int) (u * pictureWidth), pictureWidth);
		int y = clamp((int) (v * pictureHeight), pictureHeight);
		return picture[y * pictureWidth + x];
	}

	/** Blends the four nearest picture pixels, weighting colour by alpha so edges do not darken. */
	private int blended(float u, float v)
	{
		if (offPicture(u, v)) return 0;
		float fx = u * pictureWidth - 0.5f;
		float fy = v * pictureHeight - 0.5f;
		int left = (int) Math.floor(fx);
		int top = (int) Math.floor(fy);
		float tx = fx - left;
		float ty = fy - top;
		int x0 = clamp(left, pictureWidth), x1 = clamp(left + 1, pictureWidth);
		int y0 = clamp(top, pictureHeight), y1 = clamp(top + 1, pictureHeight);

		int topLeft = picture[y0 * pictureWidth + x0];
		int topRight = picture[y0 * pictureWidth + x1];
		int bottomLeft = picture[y1 * pictureWidth + x0];
		int bottomRight = picture[y1 * pictureWidth + x1];
		float wTopLeft = (1 - tx) * (1 - ty) * (topLeft >>> 24);
		float wTopRight = tx * (1 - ty) * (topRight >>> 24);
		float wBottomLeft = (1 - tx) * ty * (bottomLeft >>> 24);
		float wBottomRight = tx * ty * (bottomRight >>> 24);
		float alpha = wTopLeft + wTopRight + wBottomLeft + wBottomRight;
		if (alpha < 0.5f) return 0;
		float red = wTopLeft * ((topLeft >> 16) & 0xff) + wTopRight * ((topRight >> 16) & 0xff)
			+ wBottomLeft * ((bottomLeft >> 16) & 0xff) + wBottomRight * ((bottomRight >> 16) & 0xff);
		float green = wTopLeft * ((topLeft >> 8) & 0xff) + wTopRight * ((topRight >> 8) & 0xff)
			+ wBottomLeft * ((bottomLeft >> 8) & 0xff) + wBottomRight * ((bottomRight >> 8) & 0xff);
		float blue = wTopLeft * (topLeft & 0xff) + wTopRight * (topRight & 0xff)
			+ wBottomLeft * (bottomLeft & 0xff) + wBottomRight * (bottomRight & 0xff);
		return channel(alpha) << 24 | channel(red / alpha) << 16 | channel(green / alpha) << 8 | channel(blue / alpha);
	}

	private static int clamp(int value, int size)
	{
		return value < 0 ? 0 : value >= size ? size - 1 : value;
	}
}

package com.sailpainter;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;

/** The picture being drawn, blown up to fill the space, with whatever tool is chosen. */
class StudioCanvas extends JComponent
{
	private static final int MARGIN = 12;
	/** Grid lines appear once a picture pixel is at least this many screen pixels wide. */
	private static final int GRID_FROM = 6;
	private static final int CHECKER = 8;
	private static final Color CHECKER_LIGHT = new Color(0x55, 0x55, 0x55);
	private static final Color CHECKER_DARK = new Color(0x44, 0x44, 0x44);
	private static final Color GRID = new Color(0, 0, 0, 60);
	private static final Color OUTLINE = new Color(255, 255, 255, 160);

	interface Listener
	{
		/** A change is about to start: time to keep a copy for undo. */
		void beforeChange();

		/** The picture changed; finished is false while a stroke is still being drawn. */
		void changed(boolean finished);

		void picked(int colour);

		/** The picture pixel under the mouse, or -1, -1 off the picture. */
		void hovered(int x, int y);
	}

	private final Listener listener;
	private int width = 1;
	private int height = 1;
	private int[] pixels = new int[1];
	private BufferedImage image;

	private Tool tool = Tool.BRUSH;
	private int colour = 0xff000000;
	private int brushSize = 3;
	private boolean filled;
	private boolean mirror;
	private boolean grid = true;

	private boolean drawing;
	private int drawingColour;
	private int[] beforeShape;
	private int startX;
	private int startY;
	private int lastX;
	private int lastY;
	private int hoverX = -1;
	private int hoverY = -1;

	StudioCanvas(Listener listener)
	{
		this.listener = listener;
		setPreferredSize(new Dimension(560, 560));
		setCursor(Cursor.getPredefinedCursor(Cursor.CROSSHAIR_CURSOR));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent event)
			{
				press(event);
			}

			@Override
			public void mouseDragged(MouseEvent event)
			{
				drag(event);
			}

			@Override
			public void mouseReleased(MouseEvent event)
			{
				release();
			}

			@Override
			public void mouseMoved(MouseEvent event)
			{
				hover(event);
			}

			@Override
			public void mouseExited(MouseEvent event)
			{
				hoverX = -1;
				hoverY = -1;
				listener.hovered(-1, -1);
				repaint();
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	void setPicture(int width, int height, int[] pixels)
	{
		drawing = false;
		this.width = width;
		this.height = height;
		this.pixels = pixels;
		image = null;
		repaint();
	}

	Design snapshot()
	{
		return Design.of(width, height, pixels);
	}

	int pictureWidth()
	{
		return width;
	}

	int pictureHeight()
	{
		return height;
	}

	void setTool(Tool tool)
	{
		this.tool = tool;
		repaint();
	}

	Tool getTool()
	{
		return tool;
	}

	void setColour(int colour)
	{
		this.colour = colour;
	}

	int getColour()
	{
		return colour;
	}

	void setBrushSize(int brushSize)
	{
		this.brushSize = brushSize;
		repaint();
	}

	void setFilled(boolean filled)
	{
		this.filled = filled;
	}

	void setMirror(boolean mirror)
	{
		this.mirror = mirror;
		repaint();
	}

	void setGrid(boolean grid)
	{
		this.grid = grid;
		repaint();
	}

	private void press(MouseEvent event)
	{
		if (drawing) return;
		int x = pictureX(event.getX());
		int y = pictureY(event.getY());
		boolean inside = x >= 0 && y >= 0 && x < width && y < height;
		boolean rubOut = SwingUtilities.isRightMouseButton(event) || tool == Tool.ERASER;
		drawingColour = rubOut ? 0 : colour;

		if (tool == Tool.PICKER)
		{
			if (inside) listener.picked(pixels[y * width + x]);
			return;
		}
		if (tool == Tool.FILL)
		{
			if (!inside) return;
			listener.beforeChange();
			PixelOps.fill(pixels, width, height, x, y, drawingColour, mirror);
			changed(true);
			return;
		}

		listener.beforeChange();
		drawing = true;
		startX = x;
		startY = y;
		lastX = x;
		lastY = y;
		if (tool.isShape())
		{
			beforeShape = pixels.clone();
			drawShape(x, y, event.isShiftDown());
		}
		else
		{
			PixelOps.dab(pixels, width, height, x, y, brushSize, drawingColour, mirror);
		}
		changed(false);
	}

	private void drag(MouseEvent event)
	{
		hover(event);
		if (!drawing) return;
		int x = pictureX(event.getX());
		int y = pictureY(event.getY());
		if (x == lastX && y == lastY) return;
		if (tool.isShape())
		{
			System.arraycopy(beforeShape, 0, pixels, 0, pixels.length);
			drawShape(x, y, event.isShiftDown());
		}
		else
		{
			PixelOps.line(pixels, width, height, lastX, lastY, x, y, brushSize, drawingColour, mirror);
		}
		lastX = x;
		lastY = y;
		changed(false);
	}

	private void release()
	{
		if (!drawing) return;
		drawing = false;
		beforeShape = null;
		changed(true);
	}

	private void drawShape(int x, int y, boolean constrain)
	{
		int dx = x - startX;
		int dy = y - startY;
		if (constrain && tool == Tool.LINE)
		{
			// Snap to the nearest of horizontal, vertical and the two diagonals.
			if (Math.abs(dx) > 2 * Math.abs(dy)) dy = 0;
			else if (Math.abs(dy) > 2 * Math.abs(dx)) dx = 0;
			else dy = Integer.signum(dy) * Math.abs(dx);
		}
		else if (constrain)
		{
			int side = Math.max(Math.abs(dx), Math.abs(dy));
			dx = (dx < 0 ? -1 : 1) * side;
			dy = (dy < 0 ? -1 : 1) * side;
		}
		int endX = startX + dx;
		int endY = startY + dy;
		switch (tool)
		{
			case LINE:
				PixelOps.line(pixels, width, height, startX, startY, endX, endY, brushSize, drawingColour, mirror);
				break;
			case RECTANGLE:
				PixelOps.rectangle(pixels, width, height, startX, startY, endX, endY, brushSize, drawingColour, filled, mirror);
				break;
			case ELLIPSE:
				PixelOps.ellipse(pixels, width, height, startX, startY, endX, endY, brushSize, drawingColour, filled, mirror);
				break;
			default:
				break;
		}
	}

	private void changed(boolean finished)
	{
		image = null;
		repaint();
		listener.changed(finished);
	}

	private void hover(MouseEvent event)
	{
		int x = pictureX(event.getX());
		int y = pictureY(event.getY());
		if (x < 0 || y < 0 || x >= width || y >= height)
		{
			x = -1;
			y = -1;
		}
		if (x == hoverX && y == hoverY) return;
		hoverX = x;
		hoverY = y;
		listener.hovered(x, y);
		repaint();
	}

	/** How many screen pixels one picture pixel takes up. */
	private float scale()
	{
		float available = Math.min((getWidth() - 2f * MARGIN) / width, (getHeight() - 2f * MARGIN) / height);
		// Whole numbers keep every picture pixel the same size, once there is room for that.
		return available >= 2 ? (float) Math.floor(available) : Math.max(available, 0.1f);
	}

	private int left()
	{
		return Math.round((getWidth() - width * scale()) / 2);
	}

	private int top()
	{
		return Math.round((getHeight() - height * scale()) / 2);
	}

	private int pictureX(int screenX)
	{
		return (int) Math.floor((screenX - left()) / scale());
	}

	private int pictureY(int screenY)
	{
		return (int) Math.floor((screenY - top()) / scale());
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setColor(ColorScheme.DARKER_GRAY_COLOR);
			g.fillRect(0, 0, getWidth(), getHeight());

			float scale = scale();
			int left = left();
			int top = top();
			int drawnWidth = Math.round(width * scale);
			int drawnHeight = Math.round(height * scale);

			// A checkerboard shows through wherever the plain sail will.
			g.setClip(left, top, drawnWidth, drawnHeight);
			for (int y = 0; y < drawnHeight; y += CHECKER)
			{
				for (int x = 0; x < drawnWidth; x += CHECKER)
				{
					g.setColor(((x + y) / CHECKER) % 2 == 0 ? CHECKER_LIGHT : CHECKER_DARK);
					g.fillRect(left + x, top + y, CHECKER, CHECKER);
				}
			}
			g.setClip(null);

			if (image == null)
			{
				image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
				image.setRGB(0, 0, width, height, pixels, 0, width);
			}
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			g.drawImage(image, left, top, drawnWidth, drawnHeight, null);

			if (grid && scale >= GRID_FROM)
			{
				g.setColor(GRID);
				for (int x = 1; x < width; x++) g.drawLine(left + Math.round(x * scale), top, left + Math.round(x * scale), top + drawnHeight - 1);
				for (int y = 1; y < height; y++) g.drawLine(left, top + Math.round(y * scale), left + drawnWidth - 1, top + Math.round(y * scale));
			}
			if (mirror)
			{
				g.setColor(OUTLINE);
				g.setStroke(new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 1, new float[]{4, 4}, 0));
				int middle = left + drawnWidth / 2;
				g.drawLine(middle, top, middle, top + drawnHeight - 1);
				g.setStroke(new BasicStroke(1));
			}
			g.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
			g.drawRect(left - 1, top - 1, drawnWidth + 1, drawnHeight + 1);

			// Where the brush will land.
			if (hoverX >= 0 && !drawing && (tool == Tool.BRUSH || tool == Tool.ERASER || tool.isShape()))
			{
				int size = brushSize;
				int start = size / 2;
				g.setColor(OUTLINE);
				g.drawRect(left + Math.round((hoverX - start) * scale), top + Math.round((hoverY - start) * scale),
					Math.round(size * scale) - 1, Math.round(size * scale) - 1);
			}
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.sailpainter;

