/** A window to draw the sail's picture in. The sail follows along as you draw. */
class StudioWindow extends JFrame implements StudioCanvas.Listener
{
	private static final int[] SIZES = {32, 64, 128, 256};
	private static final int UNDO_LIMIT = 100;
	/** While a stroke is being drawn the sail is brought up to date at most this often. */
	private static final long LIVE_MS = 40;
	private static final int MAX_BRUSH = 32;
	private static final int[] PALETTE = {
		0x000000, 0x3c3c3c, 0x7d7d7d, 0xbebebe,
		0xffffff, 0xf2eee3, 0xe0c9a6, 0xc19a6b,
		0x8b5a2b, 0x4a2c17, 0x6b1d1d, 0xc0392b,
		0xff6f61, 0xf39c12, 0xf7dc6f, 0xfff3b0,
		0x1e5631, 0x27ae60, 0x8fd694, 0x0e6655,
		0x48c9b0, 0x1b2a6b, 0x2e86de, 0x85c1e9,
		0x5b2c6f, 0x9b59b6, 0xd7a9e3, 0xff8fc7,
	};

	private final SailPainterPlugin plugin;
	private final StudioCanvas canvas = new StudioCanvas(this);
	private final Deque<Design> undo = new ArrayDeque<>();
	private final Deque<Design> redo = new ArrayDeque<>();
	private final Map<Tool, JToggleButton> toolButtons = new EnumMap<>(Tool.class);
	private final JLabel position = new JLabel(" ");
	private final Swatch current = new Swatch(0xff000000, 44);
	private final JSlider brush = new JSlider(1, MAX_BRUSH, 3);
	private final JLabel brushLabel = new JLabel("3");
	private final JComboBox<String> sizes = new JComboBox<>();
	private final JCheckBox grid = new JCheckBox("Show grid", true);
	private final JCheckBox mirror = new JCheckBox("Mirror drawing");
	private final JButton undoButton = new JButton("Undo");
	private final JButton redoButton = new JButton("Redo");
	private Tool beforePicker = Tool.BRUSH;
	private boolean loaded;
	private boolean updatingSizes;
	private long lastLive;

	StudioWindow(SailPainterPlugin plugin)
	{
		super("Sail Painter Studio");
		this.plugin = plugin;
		setIconImage(ImageUtil.loadImageResource(SailPainterPlugin.class, "panel_icon.png"));
		setDefaultCloseOperation(HIDE_ON_CLOSE);

		JPanel content = new JPanel(new BorderLayout());
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.add(toolbars(), BorderLayout.NORTH);
		content.add(canvas, BorderLayout.CENTER);
		content.add(palette(), BorderLayout.EAST);
		content.add(statusBar(), BorderLayout.SOUTH);
		setContentPane(content);
		bindKeys();
		selectTool(Tool.BRUSH);
		updateButtons();

		pack();
		setMinimumSize(new Dimension(760, 560));
		setLocationRelativeTo(null);
	}

	/** Shows the given design, keeping what was there before on the undo list. */
	void load(Design design)
	{
		Design shown = canvas.snapshot();
		if (loaded && shown.width() == design.width() && shown.height() == design.height()
			&& Arrays.equals(shown.pixels(), design.pixels()))
		{
			return;
		}
		if (loaded) remember(shown);
		loaded = true;
		canvas.setPicture(design.width(), design.height(), design.copyPixels());
		showSize();
		updateButtons();
	}

	@Override
	public void beforeChange()
	{
		remember(canvas.snapshot());
		updateButtons();
	}

	@Override
	public void changed(boolean finished)
	{
		long now = System.currentTimeMillis();
		if (!finished && now - lastLive < LIVE_MS) return;
		lastLive = now;
		plugin.setDesign(canvas.snapshot(), finished, this);
	}

	@Override
	public void picked(int colour)
	{
		setColour(colour);
		selectTool(beforePicker);
	}

	@Override
	public void hovered(int x, int y)
	{
		String size = canvas.pictureWidth() + " × " + canvas.pictureHeight();
		position.setText(x < 0 ? size : x + ", " + y + "     " + size);
	}

	private JComponent toolbars()
	{
		JPanel tools = row();
		ButtonGroup group = new ButtonGroup();
		for (Tool tool : Tool.values())
		{
			JToggleButton button = new JToggleButton(tool.label);
			button.setToolTipText(tool.tooltip);
			button.setFocusable(false);
			button.addActionListener(event -> selectTool(tool));
			group.add(button);
			toolButtons.put(tool, button);
			tools.add(button);
		}
		tools.add(separator());
		tools.add(new JLabel("Size"));
		brush.setFocusable(false);
		brush.setPreferredSize(new Dimension(120, brush.getPreferredSize().height));
		brush.setToolTipText("Brush and line thickness ([ and ])");
		brush.addChangeListener(event ->
		{
			brushLabel.setText(String.valueOf(brush.getValue()));
			canvas.setBrushSize(brush.getValue());
		});
		canvas.setBrushSize(brush.getValue());
		tools.add(brush);
		brushLabel.setPreferredSize(new Dimension(20, brushLabel.getPreferredSize().height));
		tools.add(brushLabel);

		JPanel actions = row();
		undoButton.setToolTipText("Undo (Ctrl+Z)");
		undoButton.addActionListener(event -> undo());
		actions.add(button(undoButton));
		redoButton.setToolTipText("Redo (Ctrl+Y)");
		redoButton.addActionListener(event -> redo());
		actions.add(button(redoButton));
		JButton clear = new JButton("Clear");
		clear.setToolTipText("Rub out everything, back to the plain sail");
		clear.addActionListener(event -> replace(Design.blank(canvas.pictureWidth(), canvas.pictureHeight())));
		actions.add(button(clear));
		actions.add(separator());

		actions.add(new JLabel("Canvas"));
		for (int size : SIZES) sizes.addItem(size + " × " + size);
		sizes.setFocusable(false);
		sizes.setToolTipText("How many pixels the picture has. Changing it stretches what is already drawn");
		sizes.addActionListener(event ->
		{
			int index = sizes.getSelectedIndex();
			if (updatingSizes || index < 0) return;
			int size = SIZES[index];
			if (size == canvas.pictureWidth() && size == canvas.pictureHeight()) return;
			replace(canvas.snapshot().resized(size, size));
		});
		actions.add(sizes);

		JButton examples = new JButton("Examples");
		examples.setToolTipText("Start from a ready-made design. Test pattern shows which way up and round the picture lands");
		JPopupMenu menu = new JPopupMenu();
		for (Examples example : Examples.values())
		{
			JMenuItem item = new JMenuItem(example.toString());
			item.addActionListener(event -> replace(example.draw(canvas.pictureWidth(), canvas.pictureHeight())));
			menu.add(item);
		}
		examples.addActionListener(event -> menu.show(examples, 0, examples.getHeight()));
		actions.add(button(examples));
		actions.add(separator());

		JButton open = new JButton("Import…");
		open.setToolTipText("Use a picture from your computer");
		open.addActionListener(event ->
		{
			BufferedImage image = DesignFiles.open(this);
			if (image != null) replace(Design.fromImage(image, SailPainterPlugin.IMPORT_SIZE));
		});
		actions.add(button(open));
		JButton save = new JButton("Export…");
		save.setToolTipText("Save the picture as a PNG");
		save.addActionListener(event -> DesignFiles.save(this, canvas.snapshot()));
		actions.add(button(save));

		JPanel bars = new JPanel();
		bars.setLayout(new BoxLayout(bars, BoxLayout.Y_AXIS));
		bars.setBackground(ColorScheme.DARK_GRAY_COLOR);
		bars.add(tools);
		bars.add(actions);
		return bars;
	}

	private JComponent palette()
	{
		JPanel panel = new JPanel(new BorderLayout(0, 10));
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(12, 4, 12, 12));

		JPanel top = new JPanel(new BorderLayout(8, 0));
		top.setBackground(ColorScheme.DARK_GRAY_COLOR);
		current.setToolTipText("The colour you are drawing with. Click to choose any colour");
		current.onClick(this::chooseColour);
		top.add(current, BorderLayout.WEST);
		top.add(new JLabel("Colour"), BorderLayout.CENTER);
		panel.add(top, BorderLayout.NORTH);

		JPanel swatches = new JPanel(new GridLayout(0, 4, 4, 4));
		swatches.setBackground(ColorScheme.DARK_GRAY_COLOR);
		for (int rgb : PALETTE)
		{
			Swatch swatch = new Swatch(0xff000000 | rgb, 26);
			swatch.onClick(() -> setColour(swatch.colour));
			swatches.add(swatch);
		}
		JButton more = new JButton("More colours…");
		more.setFocusable(false);
		more.addActionListener(event -> chooseColour());

		JCheckBox filled = new JCheckBox("Filled shapes");
		filled.setFocusable(false);
		filled.setToolTipText("Fill boxes and ovals rather than only outlining them");
		filled.addActionListener(event -> canvas.setFilled(filled.isSelected()));
		mirror.setFocusable(false);
		mirror.setToolTipText("Draw everything again reflected left to right, for symmetrical designs (M)");
		mirror.addActionListener(event -> canvas.setMirror(mirror.isSelected()));
		grid.setFocusable(false);
		grid.setToolTipText("Show lines between pixels when zoomed in (G)");
		grid.addActionListener(event -> canvas.setGrid(grid.isSelected()));

		JPanel column = new JPanel(new GridLayout(0, 1, 0, 6));
		column.setBackground(ColorScheme.DARK_GRAY_COLOR);
		column.add(more);
		column.add(new JLabel());
		column.add(filled);
		column.add(mirror);
		column.add(grid);

		JPanel holder = new JPanel(new BorderLayout(0, 10));
		holder.setBackground(ColorScheme.DARK_GRAY_COLOR);
		holder.add(swatches, BorderLayout.NORTH);
		holder.add(column, BorderLayout.CENTER);
		JPanel stack = new JPanel(new BorderLayout());
		stack.setBackground(ColorScheme.DARK_GRAY_COLOR);
		stack.add(holder, BorderLayout.NORTH);
		panel.add(stack, BorderLayout.CENTER);
		return panel;
	}

	private JComponent statusBar()
	{
		JPanel bar = new JPanel(new BorderLayout());
		bar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		bar.setBorder(BorderFactory.createEmptyBorder(4, 10, 4, 10));
		bar.add(position, BorderLayout.WEST);
		JLabel hint = new JLabel("Your sail updates as you draw.  Right-click rubs out.  Ctrl+Z undoes.", SwingConstants.RIGHT);
		hint.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		bar.add(hint, BorderLayout.EAST);
		return bar;
	}

	private void bindKeys()
	{
		JRootPane root = getRootPane();
		int menu = Toolkit.getDefaultToolkit().getMenuShortcutKeyMaskEx();
		bind(root, KeyStroke.getKeyStroke(KeyEvent.VK_Z, menu), "undo", this::undo);
		bind(root, KeyStroke.getKeyStroke(KeyEvent.VK_Y, menu), "redo", this::redo);
		bind(root, KeyStroke.getKeyStroke(KeyEvent.VK_Z, menu | InputEvent.SHIFT_DOWN_MASK), "redo again", this::redo);
		for (Tool tool : Tool.values()) bind(root, KeyStroke.getKeyStroke(tool.key, 0), "tool " + tool, () -> selectTool(tool));
		bind(root, KeyStroke.getKeyStroke(KeyEvent.VK_OPEN_BRACKET, 0), "smaller", () -> brush.setValue(brush.getValue() - 1));
		bind(root, KeyStroke.getKeyStroke(KeyEvent.VK_CLOSE_BRACKET, 0), "bigger", () -> brush.setValue(brush.getValue() + 1));
		bind(root, KeyStroke.getKeyStroke(KeyEvent.VK_G, 0), "grid", grid::doClick);
		bind(root, KeyStroke.getKeyStroke(KeyEvent.VK_M, 0), "mirror", mirror::doClick);
	}

	private void selectTool(Tool tool)
	{
		if (tool == Tool.PICKER && canvas.getTool() != Tool.PICKER) beforePicker = canvas.getTool();
		canvas.setTool(tool);
		toolButtons.get(tool).setSelected(true);
	}

	private void setColour(int colour)
	{
		canvas.setColour(colour);
		current.setColour(colour);
		// Choosing a colour means wanting to paint with it.
		if (canvas.getTool() == Tool.ERASER) selectTool(Tool.BRUSH);
	}

	private void chooseColour()
	{
		Color chosen = JColorChooser.showDialog(this, "Choose a colour", new Color(canvas.getColour(), true));
		if (chosen != null) setColour(chosen.getRGB());
	}

	/** Swaps in a whole new picture as one undoable step. */
	private void replace(Design design)
	{
		beforeChange();
		show(design);
	}

	private void undo()
	{
		if (undo.isEmpty()) return;
		redo.push(canvas.snapshot());
		show(undo.pop());
	}

	private void redo()
	{
		if (redo.isEmpty()) return;
		undo.push(canvas.snapshot());
		show(redo.pop());
	}

	private void show(Design design)
	{
		canvas.setPicture(design.width(), design.height(), design.copyPixels());
		showSize();
		updateButtons();
		plugin.setDesign(design, true, this);
	}

	/** Keeps a copy for undo. Any change other than an undo or redo also ends the chance to redo. */
	private void remember(Design design)
	{
		undo.push(design);
		while (undo.size() > UNDO_LIMIT) undo.removeLast();
		redo.clear();
	}

	private void showSize()
	{
		updatingSizes = true;
		int index = -1;
		for (int i = 0; i < SIZES.length; i++)
		{
			if (SIZES[i] == canvas.pictureWidth() && SIZES[i] == canvas.pictureHeight()) index = i;
		}
		sizes.setSelectedIndex(index);
		updatingSizes = false;
		hovered(-1, -1);
	}

	private void updateButtons()
	{
		undoButton.setEnabled(!undo.isEmpty());
		redoButton.setEnabled(!redo.isEmpty());
	}

	private static JPanel row()
	{
		JPanel row = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 4));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		return row;
	}

	private static JButton button(JButton button)
	{
		button.setFocusable(false);
		return button;
	}

	private static JComponent separator()
	{
		JSeparator separator = new JSeparator(SwingConstants.VERTICAL);
		separator.setPreferredSize(new Dimension(8, 22));
		return separator;
	}

	private static void bind(JComponent component, KeyStroke key, String name, Runnable action)
	{
		component.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW).put(key, name);
		component.getActionMap().put(name, new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent event)
			{
				action.run();
			}
		});
	}

	/** A square of colour, with a checkerboard showing through any transparency. */
	private static class Swatch extends JComponent
	{
		private int colour;

		Swatch(int colour, int size)
		{
			this.colour = colour;
			setPreferredSize(new Dimension(size, size));
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		}

		void setColour(int colour)
		{
			this.colour = colour;
			repaint();
		}

		void onClick(Runnable action)
		{
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent event)
				{
					action.run();
				}
			});
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			int w = getWidth();
			int h = getHeight();
			int half = Math.max(1, Math.min(w, h) / 4);
			for (int y = 0; y < h; y += half)
			{
				for (int x = 0; x < w; x += half)
				{
					g.setColor(((x + y) / half) % 2 == 0 ? Color.LIGHT_GRAY : Color.GRAY);
					g.fillRect(x, y, half, half);
				}
			}
			g.setColor(new Color(colour, true));
			g.fillRect(0, 0, w, h);
			g.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
			g.drawRect(0, 0, w - 1, h - 1);
		}
	}
}

package com.sailpainter;

import java.awt.event.KeyEvent;

enum Tool
{
	BRUSH("Brush", KeyEvent.VK_B, "Draw freehand (B). Right-click rubs out"),
	ERASER("Eraser", KeyEvent.VK_E, "Rub out back to the plain sail (E)"),
	FILL("Fill", KeyEvent.VK_F, "Fill an area of one colour (F)"),
	PICKER("Pick", KeyEvent.VK_I, "Pick up a colour from the picture (I)"),
	LINE("Line", KeyEvent.VK_L, "Drag a straight line (L). Hold Shift to keep to 45 degrees"),
	RECTANGLE("Box", KeyEvent.VK_R, "Drag a box (R). Hold Shift for a square"),
	ELLIPSE("Oval", KeyEvent.VK_O, "Drag an oval (O). Hold Shift for a circle");

	final String label;
	final int key;
	final String tooltip;

	Tool(String label, int key, String tooltip)
	{
		this.label = label;
		this.key = key;
		this.tooltip = tooltip;
	}

	/** Tools that drag out a shape, previewed until the mouse is let go. */
	boolean isShape()
	{
		return this == LINE || this == RECTANGLE || this == ELLIPSE;
	}
}

package com.sailpainter;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Base64;
import java.util.Random;
import org.junit.Test;

public class DesignTest
{
	@Test
	public void blankUntilSomethingIsDrawn()
	{
		assertTrue(Design.blank(4, 4).isBlank());
		assertFalse(Design.of(1, 2, new int[]{0, 0x01000000}).isBlank());
	}

	@Test
	public void keepsItsOwnCopy()
	{
		int[] pixels = {0xff000001};
		Design design = Design.of(1, 1, pixels);
		pixels[0] = 0;
		assertEquals(0xff000001, design.pixel(0, 0));
	}

	@Test
	public void resizingKeepsPixelsSharp()
	{
		Design design = Design.of(2, 1, new int[]{0xffff0000, 0xff0000ff});
		Design bigger = design.resized(4, 2);
		assertArrayEquals(new int[]{0xffff0000, 0xffff0000, 0xff0000ff, 0xff0000ff, 0xffff0000, 0xffff0000, 0xff0000ff, 0xff0000ff}, bigger.pixels());
	}

	@Test
	public void bigPicturesAreShrunkToFit()
	{
		BufferedImage image = new BufferedImage(1000, 500, BufferedImage.TYPE_INT_ARGB);
		Design design = Design.fromImage(image, 256);
		assertEquals(256, design.width());
		assertEquals(128, design.height());
	}

	@Test
	public void smallPicturesKeepTheirSize()
	{
		BufferedImage image = new BufferedImage(32, 20, BufferedImage.TYPE_INT_ARGB);
		Design design = Design.fromImage(image, 256);
		assertEquals(32, design.width());
		assertEquals(20, design.height());
	}

	@Test
	public void pngKeepsEveryPixel() throws Exception
	{
		int[] pixels = {0xffff0000, 0x00000000, 0x80123456, 0xffffffff};
		byte[] png = DesignCodec.png(Design.of(2, 2, pixels));
		Design loaded = Design.fromImage(DesignCodec.read(new ByteArrayInputStream(png), 10), Design.MAX_SIZE);
		assertEquals(2, loaded.width());
		assertEquals(0xffff0000, loaded.pixel(0, 0));
		assertEquals(0, loaded.pixel(1, 0) >>> 24);
		assertEquals(0x80123456, loaded.pixel(0, 1));
	}

	@Test(expected = IOException.class)
	public void oversizedPicturesAreRefusedBeforeDecoding() throws Exception
	{
		byte[] png = DesignCodec.png(Design.blank(64, 8));
		DesignCodec.read(new ByteArrayInputStream(png), 32);
	}

	@Test(expected = IOException.class)
	public void nonPicturesAreRefused() throws Exception
	{
		DesignCodec.read(new ByteArrayInputStream("not a picture".getBytes(StandardCharsets.UTF_8)), 32);
	}

	@Test
	public void sharedDesignComesBackTheSame() throws Exception
	{
		Design design = Examples.JOLLY_ROGER.draw(64, 64);
		Design received = DesignCodec.unshare(DesignCodec.share(design));
		assertArrayEquals(design.pixels(), received.pixels());
	}

	@Test
	public void detailedDesignsShrinkToShare() throws Exception
	{
		// Noise does not compress, so a 256 square of it is far over the limit.
		Random random = new Random(1);
		int[] noise = new int[256 * 256];
		for (int i = 0; i < noise.length; i++) noise[i] = 0xff000000 | random.nextInt(0x1000000);
		String text = DesignCodec.share(Design.of(256, 256, noise));
		assertTrue(Base64.getDecoder().decode(text).length <= DesignCodec.MAX_SHARED_BYTES);
		assertTrue(DesignCodec.unshare(text).width() < 256);
	}

	@Test(expected = IOException.class)
	public void oversizedSharedTextIsRefused() throws Exception
	{
		char[] text = new char[DesignCodec.MAX_SHARED_BYTES * 2];
		Arrays.fill(text, 'A');
		DesignCodec.unshare(new String(text));
	}

	@Test(expected = IOException.class)
	public void garbledSharedTextIsRefused() throws Exception
	{
		DesignCodec.unshare("this is %% not base64");
	}

	@Test
	public void examplesFillTheCanvas()
	{
		for (Examples example : Examples.values())
		{
			Design design = example.draw(64, 32);
			assertEquals(64, design.width());
			assertEquals(32, design.height());
			assertFalse(example + " is blank", design.isBlank());
		}
	}
}

package com.sailpainter;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class PixelOpsTest
{
	private static final int SIZE = 16;
	private static final int INK = 0xff112233;

	private final int[] pixels = new int[SIZE * SIZE];

	@Test
	public void smallestDabIsOnePixel()
	{
		PixelOps.dab(pixels, SIZE, SIZE, 5, 6, 1, INK, false);
		assertEquals(1, count());
		assertEquals(INK, at(5, 6));
	}

	@Test
	public void roundDabIsCentredAndRound()
	{
		PixelOps.dab(pixels, SIZE, SIZE, 8, 8, 5, INK, false);
		assertEquals(INK, at(8, 8));
		assertEquals(INK, at(6, 8));
		assertEquals(INK, at(10, 8));
		assertEquals(0, at(6, 6));
		assertEquals(0, at(11, 8));
	}

	@Test
	public void dabOffTheEdgeIsClipped()
	{
		PixelOps.dab(pixels, SIZE, SIZE, 0, 0, 3, INK, false);
		assertEquals(4, count());
	}

	@Test
	public void mirrorDrawsBothSides()
	{
		PixelOps.dab(pixels, SIZE, SIZE, 2, 3, 1, INK, true);
		assertEquals(INK, at(2, 3));
		assertEquals(INK, at(SIZE - 3, 3));
		assertEquals(2, count());
	}

	@Test
	public void mirroredEvenDabIsSymmetrical()
	{
		PixelOps.dab(pixels, SIZE, SIZE, 3, 3, 2, INK, true);
		for (int y = 0; y < SIZE; y++)
		{
			for (int x = 0; x < SIZE; x++) assertEquals(at(x, y), at(SIZE - 1 - x, y));
		}
	}

	@Test
	public void lineHasNoGaps()
	{
		PixelOps.line(pixels, SIZE, SIZE, 1, 1, 14, 6, 1, INK, false);
		assertEquals(14, count());
		assertEquals(INK, at(1, 1));
		assertEquals(INK, at(14, 6));
	}

	@Test
	public void fillStopsAtOutlines()
	{
		PixelOps.rectangle(pixels, SIZE, SIZE, 2, 2, 8, 8, 1, INK, false, false);
		PixelOps.fill(pixels, SIZE, SIZE, 5, 5, 0xffff0000, false);
		assertEquals(0xffff0000, at(5, 5));
		assertEquals(INK, at(2, 5));
		assertEquals(0, at(12, 12));
		assertEquals(5 * 5, countOf(0xffff0000));
	}

	@Test
	public void fillOfSameColourDoesNothing()
	{
		PixelOps.fill(pixels, SIZE, SIZE, 0, 0, 0, false);
		assertEquals(0, count());
	}

	@Test
	public void filledRectangleCoversCorners()
	{
		PixelOps.rectangle(pixels, SIZE, SIZE, 9, 9, 3, 3, 1, INK, true, false);
		assertEquals(7 * 7, count());
	}

	@Test
	public void ellipseOutlineLeavesMiddleEmpty()
	{
		PixelOps.ellipse(pixels, SIZE, SIZE, 0, 0, 15, 15, 1, INK, false, false);
		assertEquals(0, at(8, 8));
		assertEquals(INK, at(8, 0));
		assertEquals(0, at(0, 0));
	}

	private int at(int x, int y)
	{
		return pixels[y * SIZE + x];
	}

	private int count()
	{
		int count = 0;
		for (int pixel : pixels)
		{
			if (pixel != 0) count++;
		}
		return count;
	}

	private int countOf(int colour)
	{
		int count = 0;
		for (int pixel : pixels)
		{
			if (pixel == colour) count++;
		}
		return count;
	}
}

package com.sailpainter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SailMeshTest
{
	private static final int CLOTH_COLOUR = (10 << 10) | (3 << 7) | 90;
	private static final int ROPE_COLOUR = (5 << 10) | (2 << 7) | 40;

	/**
	 * A flat sail 200 wide and 300 tall standing in the x-y plane, as two layers facing opposite ways,
	 * with a thin rope hanging below it.
	 */
	private static final float[] X = {-100, 100, -100, 100, -2, 2, -2};
	private static final float[] Y = {-300, -300, 0, 0, 0, 0, 100};
	private static final float[] Z = {0, 0, 0, 0, 0, 0, 0};
	// Faces 0 and 1 face one way, 2 and 3 the other, 4 is the rope.
	private static final int[] F1 = {0, 1, 0, 1, 4};
	private static final int[] F2 = {2, 2, 1, 3, 6};
	private static final int[] F3 = {1, 3, 2, 2, 5};

	@Test
	public void ropeIsNotCloth()
	{
		SailMesh mesh = build(false);
		assertEquals(4, mesh.clothFaces);
		assertEquals(SailMesh.SOLID, mesh.kind[4]);
		assertEquals(SailMesh.CLOTH, mesh.kind[0]);
	}

	@Test
	public void wholeModelPaintsTheRopeToo()
	{
		SailMesh mesh = build(true);
		assertEquals(5, mesh.clothFaces);
	}

	@Test
	public void hiddenFacesAreLeftOut()
	{
		SailMesh mesh = new SailMesh();
		int[] colours = {CLOTH_COLOUR, CLOTH_COLOUR, CLOTH_COLOUR, CLOTH_COLOUR, ROPE_COLOUR};
		int[] third = {-2, -1, -1, -1, -1};
		mesh.build(7, X, Y, Z, 5, F1, F2, F3, colours, colours, third, unlit(), null, null, false);
		assertEquals(SailMesh.HIDDEN, mesh.kind[0]);
		assertEquals(3, mesh.clothFaces);
	}

	@Test
	public void pictureRunsAcrossAndDownTheCloth()
	{
		SailMesh mesh = build(false);
		// Top left, top right, bottom left, bottom right of the cloth.
		assertEquals(0, mesh.u[0], 1e-4);
		assertEquals(0, mesh.v[0], 1e-4);
		assertEquals(1, mesh.u[1], 1e-4);
		assertEquals(0, mesh.v[1], 1e-4);
		assertEquals(0, mesh.u[2], 1e-4);
		assertEquals(1, mesh.v[2], 1e-4);
		assertEquals(1, mesh.u[3], 1e-4);
		assertEquals(1, mesh.v[3], 1e-4);
	}

	@Test
	public void sailTurnedSidewaysStillMapsAcross()
	{
		SailMesh mesh = new SailMesh();
		// The same sail stretched along z instead of x.
		int[] colours = colours();
		mesh.build(7, Z, Y, X, 5, F1, F2, F3, colours, colours, minusOnes(), unlit(), null, null, false);
		assertEquals(0, mesh.u[0], 1e-4);
		assertEquals(1, mesh.u[1], 1e-4);
		assertEquals(0, mesh.v[1], 1e-4);
		assertEquals(1, mesh.v[3], 1e-4);
	}

	@Test
	public void shadingComesFromLitAgainstUnlit()
	{
		SailMesh mesh = shadedInShadowOnFront();
		assertEquals(0.5f, mesh.shade[0], 1e-4);
		assertEquals(1f, mesh.shade[6], 1e-4);
	}

	@Test
	public void shadingAveragesOneOnTheSideInView()
	{
		SailMesh mesh = shadedInShadowOnFront();
		mesh.project(front(), 0, 0, 0, 0);
		assertEquals(2f, mesh.shadeScale(), 1e-4);
		mesh.project(behind(), 0, 0, 0, 0);
		assertEquals(1f, mesh.shadeScale(), 1e-4);
	}

	/** The faces towards the front are half as bright as their colour; the back ones are lit fully. */
	private static SailMesh shadedInShadowOnFront()
	{
		SailMesh mesh = new SailMesh();
		int dark = (CLOTH_COLOUR & ~0x7f) | 45;
		int light = (CLOTH_COLOUR & ~0x7f) | 90;
		int[] first = {dark, dark, light, light, ROPE_COLOUR};
		mesh.build(7, X, Y, Z, 5, F1, F2, F3, first, first, minusOnes(), unlit(), null, null, false);
		return mesh;
	}

	@Test
	public void squareSailFitsThePictureWhole()
	{
		SailMesh mesh = build(false);
		mesh.fitInside(new float[4]);
		assertEquals(0, mesh.fitLeft, 1e-4);
		assertEquals(0, mesh.fitTop, 1e-4);
		assertEquals(1, mesh.fitRight, 1e-4);
		assertEquals(1, mesh.fitBottom, 1e-4);
	}

	@Test
	public void triangularSailFitsTheBiggestBoxInside()
	{
		SailMesh mesh = triangle();
		mesh.fitInside(new float[4]);
		// The cloth is the lower left half, so the biggest box is the quarter in its square corner.
		assertEquals(0, mesh.fitLeft, 0.05);
		assertEquals(0.5, mesh.fitTop, 0.05);
		assertEquals(0.5, mesh.fitRight, 0.05);
		assertEquals(1, mesh.fitBottom, 0.05);
	}

	@Test
	public void fittedBoxHoldsStillForSmallChanges()
	{
		SailMesh mesh = triangle();
		float[] previous = {0.01f, 0.49f, 0.51f, 1};
		mesh.fitInside(previous);
		assertEquals(0.51f, mesh.fitRight, 1e-6);
		assertEquals(0.51f, previous[2], 1e-6);

		float[] stale = {0.3f, 0.1f, 0.9f, 0.5f};
		mesh.fitInside(stale);
		assertEquals(0.5, stale[2], 0.05);
	}

	@Test
	public void stretchCoversEverything()
	{
		SailMesh mesh = triangle();
		mesh.fitInside(new float[4]);
		mesh.stretch();
		assertEquals(0, mesh.fitTop, 0);
		assertEquals(1, mesh.fitRight, 0);
	}

	/** A right-angled sail filling the lower left half of its box, as two layers. */
	private static SailMesh triangle()
	{
		SailMesh mesh = new SailMesh();
		float[] x = {-100, 100, -100};
		float[] y = {-300, 0, 0};
		float[] z = {0, 0, 0};
		int[] colours = {CLOTH_COLOUR, CLOTH_COLOUR};
		short[] unlit = {(short) CLOTH_COLOUR, (short) CLOTH_COLOUR};
		mesh.build(3, x, y, z, 2, new int[]{0, 0}, new int[]{2, 1}, new int[]{1, 2}, colours, colours, new int[]{-1, -1}, unlit, null, null, false);
		return mesh;
	}

	@Test
	public void onlyFacesTowardsTheCameraAreVisible()
	{
		SailMesh mesh = build(false);
		mesh.project(front(), 0, 0, 0, 0);
		assertTrue(mesh.visible(0));
		assertTrue(mesh.visible(1));
		assertFalse(mesh.visible(2));
		assertFalse(mesh.visible(3));
	}

	@Test
	public void pictureReadsBackwardsFromBehind()
	{
		SailMesh mesh = build(false);
		mesh.project(front(), 0, 0, 0, 0);
		assertFalse(mesh.mirrored());

		mesh.project(behind(), 0, 0, 0, 0);
		assertTrue(mesh.visible(2));
		assertTrue(mesh.mirrored());
	}

	@Test
	public void clothBoundsCoverVisibleCloth()
	{
		SailMesh mesh = build(false);
		mesh.project(front(), 0, 0, 0, 0);
		float[] bounds = {Float.MAX_VALUE, Float.MAX_VALUE, -Float.MAX_VALUE, -Float.MAX_VALUE};
		assertTrue(mesh.addClothBounds(bounds));
		assertEquals(400, bounds[0], 1e-3);
		assertEquals(100, bounds[1], 1e-3);
		assertEquals(600, bounds[2], 1e-3);
		assertEquals(400, bounds[3], 1e-3);
	}

	@Test
	public void vertexBehindCameraHidesItsFaces()
	{
		SailMesh mesh = build(false);
		mesh.project((count, x, y, z, lx, ly, lz, orientation, sx, sy, depth) ->
		{
			front().project(count, x, y, z, lx, ly, lz, orientation, sx, sy, depth);
			depth[0] = 0;
		}, 0, 0, 0, 0);
		assertFalse(mesh.visible(0));
		assertTrue(mesh.visible(1));
	}

	private static SailMesh build(boolean wholeModel)
	{
		SailMesh mesh = new SailMesh();
		int[] colours = colours();
		mesh.build(7, X, Y, Z, 5, F1, F2, F3, colours, colours, minusOnes(), unlit(), null, null, wholeModel);
		return mesh;
	}

	/** Looking straight at the sail, so model x is screen x and model y is screen y. */
	private static Projector front()
	{
		return (count, x, y, z, lx, ly, lz, orientation, sx, sy, depth) ->
		{
			for (int i = 0; i < count; i++)
			{
				sx[i] = 500 + x[i];
				sy[i] = 400 + y[i];
				depth[i] = 0.001f;
			}
		};
	}

	/** From the other side, where model x runs right to left on screen. */
	private static Projector behind()
	{
		return (count, x, y, z, lx, ly, lz, orientation, sx, sy, depth) ->
		{
			for (int i = 0; i < count; i++)
			{
				sx[i] = 500 - x[i];
				sy[i] = 400 + y[i];
				depth[i] = 0.001f;
			}
		};
	}

	private static int[] colours()
	{
		return new int[]{CLOTH_COLOUR, CLOTH_COLOUR, CLOTH_COLOUR, CLOTH_COLOUR, ROPE_COLOUR};
	}

	private static int[] minusOnes()
	{
		return new int[]{-1, -1, -1, -1, -1};
	}

	private static short[] unlit()
	{
		return new short[]{(short) CLOTH_COLOUR, (short) CLOTH_COLOUR, (short) CLOTH_COLOUR, (short) CLOTH_COLOUR, (short) ROPE_COLOUR};
	}
}

package com.sailpainter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import net.runelite.client.party.messages.WebsocketMessage;
import net.runelite.client.util.RuntimeTypeAdapterFactory;
import org.junit.Test;

/** Sends the design message through the same kind of encoding the party connection builds for registered messages. */
public class SailPainterDesignWireTest
{
	private final Gson gson = new Gson().newBuilder()
		.registerTypeAdapterFactory(RuntimeTypeAdapterFactory.of(WebsocketMessage.class).registerSubtype(SailPainterDesign.class))
		.create();

	@Test
	public void designSurvivesTheTrip()
	{
		WebsocketMessage received = trip(new SailPainterDesign("Shep FX", "iVBORw0K"));
		assertTrue(received instanceof SailPainterDesign);
		assertEquals("Shep FX", ((SailPainterDesign) received).getName());
		assertEquals("iVBORw0K", ((SailPainterDesign) received).getPng());
	}

	@Test
	public void stoppingSharingSurvivesTheTrip()
	{
		assertNull(((SailPainterDesign) trip(new SailPainterDesign("Shep FX", null))).getPng());
	}

	private WebsocketMessage trip(SailPainterDesign message)
	{
		return gson.fromJson(gson.toJson(message, WebsocketMessage.class), WebsocketMessage.class);
	}
}

